quests[28091] = { id = 28091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nYou can see them just to our west, in the canyon below. Get in there and clear them out so we can get this attack on the move.", sourceObjective = "Kill 8 Twilight Spearwarders.", completion = "Excellent. Now we can start pushing our ground forces up towards Grim Batol.", sourceObjectiveStatus = "unverified-source-field" }
quests[28092] = { id = 28092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending the Gob Squad with you. Get to the gate to the southeast and get it open. Patch should have any further instructions you'll need from there.", sourceObjective = "Lead the Gob Squad to the closed Dragonmaw Gate.\n\nIf you lose the Gob Squad, return to Warlord Krogg for reassignment.", progress = "Keep moving. We need to get that gate open.", completion = "Works like a charm, every time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28093] = { id = 28093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Forward", description = "Good work so far. We should find the entrance to Grim Batol just past the next gate.\n\nI was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon. I'm thinking if we get there soon enough, maybe I can let Ticker have a little more fun.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", sourceObjective = "Bring the Gob Squad past the northern Dragonmaw Gate to the entrance of Grim Batol.\n\nIf you are separated from the Gob Squad, return to Warlord Krogg in Wyrms' Bend to be reassigned.", progress = "Welcome, {race}.", completion = "The gate is clear. Once your people finish clearing the canyon, we will speak to your leaders about the next move.", sourceObjectiveStatus = "unverified-source-field" }
quests[28094] = { id = 28094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", sourceObjective = "Kill 30 Twilight's Hammer cultists along Wyrm's Bend as you fight towards the entrance to Grim Batol.", completion = "We make it look easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28096] = { id = 28096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Machine", description = "Come in here dear <boy/girl>, have a cigar. You're gonna go far and fly high as a ranking officer of the Forsaken. Yes, indeed, this is the good life and you are going to live it!\n\nI want you to take these orders and dispense them to the lowly scrubs that come along looking for work. Who you give what to is wholly at your discretion.\n\nWhen you're ready, mount up on my trusty skeletal steed - so they don't miss you - and start living the life! Which means just stand there and wait.", sourceObjective = "Hand out 3 Quests.", progress = "How's the \"desk job\" coming?", completion = "So how was it? Everything that you dreamed it would be? Exciting, no?\n\nNo?\n\n<Darthalia sighs.>\n\nI can see that you're a true hero. You need action. I guess a \"desk job\" isn't for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28097] = { id = 28097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Grim Batol", description = "Kroggs started the assault to push up the canyon. He's just past the gate to our southeast.\n\nI'm going to get the squad together to join the attack. We'll meet you down there.", sourceObjective = "Speak to Warlord Krogg in Wyrms' Bend.", completion = "The canyon is well fortified, but the distraction that the dragons are providing should be enough to allow us to break through.", sourceObjectiveStatus = "unverified-source-field" }
quests[28098] = { id = 28098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Skymaster", description = "Twilight Skymaster Richtofen is at the Twilight Aerie up above and to the southeast. No matter what we do down here, if he's not dealt with, all hope is lost for Highperch.\n\nWhile Heartrazor is too injured to help you with the fight, he can fly you up there. The rest is up to you, {name}.\n\nGood luck.", sourceObjective = "Get a flight from Heartrazor to the Twilight Aerie and deal with Twilight Skymaster Richtofen.", progress = "{name}, you must take care of Twilight Skymaster Richtofen!", completion = "The pridelings did what? They must love you deeply for freeing them.\n\nThank you, {name}. You've saved Highperch!", sourceObjectiveStatus = "unverified-source-field" }
quests[28099] = { id = 28099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasha'krak", description = "Based on this information you've delivered, I believe that one of this \"Archduke's\" minions may already have turned its eyes toward Thorium Point.\n\nHis name is Rasha'krak, and he patrols the lava pools just to our south.  He looks like the latent fire elementals that rage nearby, except for one small difference: the bracers of binding that encircle his wrists.\n\nFind him and bring these bracers to me, {name}.  I need proof that we are in danger before we involve ourselves in elemental wars.", sourceObjective = "Obtain Rasha'krak's Bracers of Binding.", progress = "I won't fight any elementals until we have proven that they pose a threat to us.", completion = "It is, unfortunately, as I expected.  These bracers bear the indelible mark of the firelord and his minions.\n\nVery well.  With no Horde or Alliance forces anywhere near this godforsaken gorge, it falls upon the Thorium Brotherhood to stop this Archduke before he spreads any more of his evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28100] = { id = 28100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Talking Totem", description = "The furbolg village to the south is the home of the Deadwood tribe, sworn enemies of the Timbermaw. They are corrupted and foul like so many others, driven mad by the taint of these woods.\n\nSomething unusual has occured near the village though. Travelers coming here have said that the totem next to the road has spoken to them.\n\nI have heard nothing every time I approach it. Perhaps it will speak to you, {name}? Maybe you can find out what's going on for me.", sourceObjective = "Speak with the Totem of Ruumbo near Deadwood Village.", completion = "You... yes, you! I have chosen you, {race}, as my champion! You will do the work of Ruumbo!", sourceObjectiveStatus = "unverified-source-field" }
quests[28101] = { id = 28101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks on Grim Batol isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Mathias Shaw in Dragonmaw Pass, in the canyon below us to the south.", sourceObjective = "Speak to Master Mathias Shaw in Dragonmaw Pass.", completion = "The red dragons have agreed to help! No small feat, I'm sure. You have the thanks of the Alliance.\n\nWe'd already laid out plans for our ambush on a Twilight caravan by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nThe battle still rages. You can definitely be of aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28102] = { id = 28102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Power", description = "It's time for the final push against the Jadefire!\n\nIf you're prepared to break through their foul barrier and bring the fight to their leader, I'd also ask your help against the lesser satyr. Our druids fight ferociously, but your strength can help turn the battle.\n\nShow the Jadefire that their power will no longer hold sway over these lands!", sourceObjective = "Slay 8 Jadefire Rogues or Jadefire Shadowstalkers at the Ruins of Constellas.", completion = "A few of the remaining satyr have fled into the deeper woods, but they have taken heavy losses. Good job, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28103] = { id = 28103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nGet in there and clear them out so we can push forward into the canyons.", sourceObjective = "Kill 8 Twilight Spearwardens.", completion = "Excellent. Now we can start pushing our ground forces up towards Grim Batol.", sourceObjectiveStatus = "unverified-source-field" }
quests[28104] = { id = 28104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed a stone that they carried in chests in their caravans that they used to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", sourceObjective = "Retrieve a Twilight Caravan Gatestone. The Spearwardens should carry keys that can get you into the gatestone chests.", progress = "They've grown overconfident. More and more, that seems the downfall of the most powerful armies.", completion = "Good going.\n\nDoesn't look like much, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[28105] = { id = 28105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kavem the Callous", description = "Kavem was cruel enough before the Neferset signed up with Deathwing.  His pleasure in deriving pain now borders on the insane.\n\nIt is he who now holds the keys to our shackles.\n\nHe dwells in the building next to us, to my right.\n\nFind him and take the key from him.  Do not hesitate or show him mercy.  He will slit your throat and think nothing of it.", sourceObjective = "Obtain the Neferset Key from Kavem the Callous.", progress = "You're back.  Do you have the key?", completion = "Excellent, {name}.  We will make our way out of here soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[28106] = { id = 28106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Grim Batol (DO NOT DELETE, DO NOT DEPRECATE!)" }
quests[28107] = { id = 28107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", sourceObjective = "Kill 30 Twilight's Hammer cultists along Wyrm's Bend as you fight towards the entrance to Grim Batol.", progress = "We're not finished yet.", completion = "We make it look easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28108] = { id = 28108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending a squad from Highbank with you. Get to the gate to the southeast and get it open. Your lieutenant should have any further instructions you'll need from there.", sourceObjective = "Lead squad from Highbank to the closed Dragonmaw Gate.\n\nIf you lose your squad, return to Master Mathias Shaw for reassignment.", progress = "Keep moving. We need to get that gate open.", completion = "Like a well-oiled machine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28109] = { id = 28109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Forward", description = "Good work so far.\n\nWe should find the entrance to Grim Batol just past the next gate. I was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", sourceObjective = "Bring your squad past the northern Dragonmaw Gate to the entrance of Grim Batol.\n\nIf you are separated from your squad, return to Master Mathias Shaw in Wyrms' Bend to be reassigned.", progress = "Welcome, {race}.", completion = "The gate is clear. Once your people finish clearing the canyon, we will speak to your leaders about the next move.", sourceObjectiveStatus = "unverified-source-field" }
quests[28111] = { id = 28111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Azurelode", description = "Productivity from our spider farm at the Azurelode Mine is at a standstill. Captain Keyton has requested that we send help immediately. Keyton claims that the mine spiders refuse command and are running rampant. Furthermore, a group of coastal murlocs are raiding our supplies. I want you to go down there and check things out. Help out Keyton and the spider-handler, {name}.\n\nYou'll find Azurelode Mine to the southeast, near the coast.", sourceObjective = "Report to Captain Keyton at the Azurelode Mine in Hillsbrad Foothills.", completion = "We're in a bit of a bind, {class}. Sarus' spiders are starting to get a little uppity as we've been unable to feed them for days. If we leave the murlocs will overtake our post! Furthermore, Warden Stillwater over at the Sludge Fields is demanding that we send him more humans! He is insatiable! We need help!", sourceObjectiveStatus = "unverified-source-field" }
quests[28112] = { id = 28112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape From the Lost City", description = "Everything is ready!  Undo my chains and set your friends free.\n\nWe must move quickly before the Neferset scum realize we're up to something!\n\nIf we make it, see my brother, King Phaoris for a reward.", sourceObjective = "Free Prince Nadun and speak to King Phaoris at Ramkahen in Uldum.", completion = "It is true then?  An outsider rescued Prince Nadun from the Neferset?\n\nWe are truly in your debt, stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[28113] = { id = 28113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Unbreakable", description = "With the claw, we are ready to break through the Jadefire's defenses.\n\nHead into the ruins to the northwest. Beyond the frontline of the satyr you'll find a narrow pass heading to their corrupted moonwell. An enormous wall of demonic flame bars the path, but the Claw of Tichondrius should be able to dispel it.\n\nBeyond the barrier you will find the leader of these forces, Xavathras, guarding the corrupted moonwell. Slay him once you are through!", sourceObjective = "Slay Xavathras.", progress = "Has Xavathras fallen?", completion = "See what can get done with a little cooperation?\n\nI'll make sure the claw is given to people responsible enough to contain such things... assuming it can't be destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28114] = { id = 28114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Harvest", description = "Directly southeast of Southpoint Gate you will find our spider domestication operations. Through the years we have grown a kinship with the spiders of Hillsbrad and have managed to domesticate and breed the adorable little critters. Spiders now serve us as regular household pets and beasts of battle! Such diverse creatures they are!\n\nI need you to head into the fields to the southeast and carefully harvest the eggs that we have incubating on the bears. Deliver the harvest to Sarus at the mine.", sourceObjective = "Recover 60 Creeper Eggs.", progress = "Have you brought my harvest?", completion = "Wonderful! Now to place these eggs into a nice, dark alcove inside the mine and let the miracle of life happen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28115] = { id = 28115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Their Prime", description = "Bears are soulless beasts put upon this earth to torment us. Only through Forsaken ingenuity have we devised a way to make use of the bears so that they may serve some purpose! We use the bears at our spider farm as living egg feeders. Our spiders lay their eggs in the bear flesh and the eggs thrive off of the meat and blood of the beasts.\n\nAfter they have served their purpose the monsters must be put down. Travel southeast and kill the infested bears that have lived past their prime.", sourceObjective = "Kill 8 Infested Bears.", completion = "The bear gods are cruel masters. They will continue to populate this world with bears until the end of days. It is our right as civilized people to make use of this nuisance - for the betterment of us all!", sourceObjectiveStatus = "unverified-source-field" }
quests[28116] = { id = 28116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crying Violet", description = "We must prepare carefully before assaulting Jaedenar. The magic of the warlocks and demons within Jaedenar is strong, and we will need wards of our own before entering.\n\nWe need only one more ingredient: Crying Violet, which grows in the hills near the enemy's stronghold to the northwest. \n\nGather the Crying Violet, then meet my assistant in the field. He will know what to do next.", sourceObjective = "Collect 8 Crying Violets.", progress = "Have you found the crying violet yet, {name}? We need them quickly.", completion = "Wonderful. Greta chose wisely when she asked you to perform this task. I will work the herbs immediately...", sourceObjectiveStatus = "unverified-source-field" }
quests[28117] = { id = 28117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed Tol Barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", sourceObjective = "You have been asked to kill 9 ghosts of any type in the Cursed Depths, just east of Baradin Hold.", completion = "You made it back out alive?  You are a stronger man than I, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28118] = { id = 28118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", sourceObjective = "You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold.", progress = "Have you been able to take out the Archmage?", completion = "Galus is dead?  Fantastic work {name}, now we can send down the cleanup crew and get that cellblock ready for new prisoners.", sourceObjectiveStatus = "unverified-source-field" }
quests[28119] = { id = 28119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purity From Corruption", description = "The flowers you brought me were the essential ingredient.\n\nProtective barriers surround Shadow Hold, projected from demonic braziers. If we are to drive the Shadow Council from Felwood, then those braziers must be extinguished.\n\nThis vial has been infused with crying violet and the magic of the wilds. Fill it at the corrupted moonwell in the center of Jaedenar and return to me.", sourceObjective = "Fill the Empty Canteen with water from the corrupted moonwell in the center of Jaedenar.", progress = "Do you have the waters from the corrupted moonwell?", completion = "This will do nicely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28120] = { id = 28120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to the Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", sourceObjective = "You have been asked to recover four Dusty Prison Journals from the Cursed Depths, just east of Baradin Hold.", progress = "Were you able to recover the journals?  Reports mentioned that they were sighted both in and out of the cells down there.", completion = "These journals are in excellent condition {name}.  We will begin deciphering them immediately.  Only time will tell what secrets they hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28121] = { id = 28121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Jaedenar", description = "The Shadow Council perpetuates the corruption of this land. At Jaedenar in the northwest, they worship the demons of the Burning Legion, and work to open the path for their masters to return to this world.\n\nThe grounds are patrolled by Jaedenar Hounds, Guardians, Adepts, and Cultists - thugs that act as lookout for the more vile forces beneath. They will be the first to die so that these forests may no longer suffer!", sourceObjective = "Slay 12 Jaedenar Forces.", completion = "Good, {name}! With their numbers weakened, we can soon begin our assault on their forces deep within Shadow Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28122] = { id = 28122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", sourceObjective = "You have been asked to kill Problim, a giant ettin that roams the paths of Tol Barad.", completion = "You actually killed him?!  I can't believe it!", sourceObjectiveStatus = "unverified-source-field" }
quests[28123] = { id = 28123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Chain", description = "Narkrall revealed to me the secret of his influence over the drakes in this area. I thought the Demon Chain was a myth, but he's had it all along.\n\nAnd now the fool is about to lose it!\n\nHis life is meaningless to me but the Dragonmaw can't afford to lose that artifact. Follow him north, up to Thundermar. The city will be in chaos, so you may be able to land undetected. Return to me with the Demon Chain, even if you have to remove it from Narkrall's corpse.\n\nFind that artifact, {name}!", sourceObjective = "Acquire the Demon Chain.", progress = "Do you have it? Yes? The fate of the Dragonmaw depends on the Demon Chain!", completion = "<Zaela takes the gore-spattered length of chain and wraps it around her hand and wrist.>\n\nIf the stories are true, {name}, it was on this length of chain that Deathwing had once fastened the Demon Soul, forged in his bid to control the other dragonflights. The Demon Soul has long been destroyed but perhaps this hunk of elementium holds some residual power...\n\nYou've done a great thing today.", sourceObjectiveStatus = "unverified-source-field" }
quests[28124] = { id = 28124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to the Bulwark", description = "{name}, while you and the pridelings were taking care of the skymaster, Lakota Windsong came by. She told me to tell you to meet her east at the Twilight Bulwark.\n\nThat must be where they're holding Magatha Grimtotem.", sourceObjective = "Speak with Lakota Windsong at the Twilight Bulwark in Thousand Needles.", completion = "I'm glad that you made it.\n\nDon't mind my new clothes. It seemed prudent to blend in.", sourceObjectiveStatus = "unverified-source-field" }
quests[28125] = { id = 28125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something to Wear", description = "I've got an idea for how you can get close to their leaders without getting killed. But first, you're going to need to find something to wear.\n\nMy suggestion is that you head up there and get their armor from them.", sourceObjective = "Collect 10 pieces of Twilight's Hammer Armor.", progress = "How much of that armor have you collected?\n\nYou're going to want to be well disguised for the next thing that you're going to have to do.", completion = "<Lakota looks worried about the condition of the armor, especially the bloodstains.>\n\nYou sure don't fool around, do you, {name}? Well, it'll have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28126] = { id = 28126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dousing the Flames of Protection", description = "The braziers are spread throughout Shadow Hold.\n\nEnter the tunnel into Shadow Hold, and follow it through the underground passageways. Douse each of the brazier's flames and the protections the Council has set up will fall for at least a short period of time.", sourceObjective = "Use the Purified Moonwell Water to douse the four Braziers of Protection within Shadow Hold.", completion = "With the braziers gone, the druids of the Emerald Circle can enter Shadow Hold and clear out the last of the cultists. In time, it may even be used as the barrow den it once was.\n\nYou have my thanks, {name}. Please take this reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[28127] = { id = 28127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Them Out", description = "Magatha's not the only one that the Twilight's Hammer have taken prisoner.\n\nWhile you're up there to the south, you should break as many of them out as you can.", sourceObjective = "Rescue 5 Bulwark Prisoners from the Twilight Jailers.", completion = "You give so much of yourself without requiring anything in return.\n\nThe people of Thousand Needles are grateful, as am I.", sourceObjectiveStatus = "unverified-source-field" }
quests[28128] = { id = 28128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inner Circle", description = "With their outer sentries gone, the greater members of the Shadow Council are next.\n\nDeep within the corrupted barrow dens you'll find powerful Jaedenar Warlocks, Hunters, Enforcers, Darkweavers, and Legionnaires.\n\nThey must be defeated if these lands are to be saved!", sourceObjective = "Slay 12 defenders inside Shadow Hold.", completion = "The cleansing of Shadow Hold will take much time and effort, but without your defeat of the Shadow Council, it would not be possible at all. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28129] = { id = 28129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Prince", description = "The Jadefire satyr that have overrun so much of Felwood work directly with the Shadow Council.\n\nThese satyr answer directly to the ancient and powerful Prince Xavalis. Some say he is the son of Xavius, the first satyr, blessed by Sargeras himself.\n\nWhatever his nature, he must die if we are to scatter the Jadefire and reclaim our barrow dens. Journey deep into Shadow Hold and slay him. Show him no mercy; he will have none for you.", sourceObjective = "Slay Prince Xavalis.", completion = "The demons begin to fall! Take heed, {class}. You will find even stronger foes deeper within Shadow Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28130] = { id = 28130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", sourceObjective = "Commander Marcus Johnson has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side.", completion = "Told you that village was full of wackos.  Nice job clearing it out {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28131] = { id = 28131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twin Temptresses", description = "Moora and Salia are the personal servants of Shadow Lord Fel'dan. Do not be deceived by them!\n\nThese foul succubi use their wiles and foul magic to draw mortals deep into Shadow Hold. Those in their grasp undergo brainwashing, or are sacrificed by Fel'dan to his demonic masters.\n\nThe two fight as one and are never found apart, making them a considerable threat. Proceed further into Shadow Hold and slay them.", sourceObjective = "Slay Moora and Salia.", progress = "Rest a while before continuing, {class}.", completion = "Another demonic menace gone. It is time to find their master.", sourceObjectiveStatus = "unverified-source-field" }
quests[28132] = { id = 28132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", sourceObjective = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", completion = "Oh look, it's one of little Schnottz's pamphlets.\n\nI'll just be taking that from you, if you don't mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28133] = { id = 28133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Unbound", description = "Narkrall's drake Torth survived the failed attack on Thundermar, and now the creature is free from his former master.\n\nTorth seeks vengeance against the Dragonmaw, and has already strafed Bloodgulch once. He will keep returning until we skewer him for good. It is time to put the Demon Chain to work.\n\nTorth's old nest is a small cave in the hills west of here that we have turned into a small camp called \"The Gullet.\"\n\nMeet me at the Gullet and we will finish Torth off.", sourceObjective = "Travel to the Gullet and speak with Zaela. Kill Torth.", progress = "Our dominance over the dragons is both our strength and our curse. Their wrath is a terrible thing to behold.", completion = "Once free of the chain, Torth died rather than submit again. I admire the creature. I will have his hide fashioned into a set of armor.\n\nThis much is clear to me now: The Dragonmaw cannot stand alone if the Alliance backs the Wildhammer. Narkrall proved that. And you have proven the might of the Horde, again and again.\n\nI will rebuild our drake wings and take up position outside the Bastion of Twilight. You should continue to help out here in the Gullet and elsewhere in the Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[28134] = { id = 28134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Retribution", description = "Now that you've been suitably rewarded, I hope I can speak with you frankly.\n\nYou've done my kingdom a great favor, but you've also unbalanced a fragile peace process.\n\nI was pursuing my brother's release strictly through diplomatic means in order to avoid bloodshed.\n\nNow, the enemy is sure to seek retaliation.\n\nSpeak to Nomarch Teneth at the Tahret Grounds to the east, Sun Priest Asaris at the Seal of the Sun King to the north and Asaq at Mar'at to the west.  Find out where the enemy will strike.", sourceObjective = "Speak to Nomarch Teneth at the Tahret Grounds, Sun Priest Asaris at the Seal of the Sun King, and Asaq at Mar'at.", progress = "You've returned, {name}.  Have you completed the task I request of you?", completion = "Orsis!  Of course!\n\nHow could I not have seen this?", sourceObjectiveStatus = "unverified-source-field" }
quests[28135] = { id = 28135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akir's Vengeance", description = "Listen, {name}.  What struck Orsis was no natural sandstorm.  It was the minions of Al'Akir.\n\nThe elemental lord of air is firmly allied with Deathwing and it was only a matter of time before he set his subjects upon my people.\n\nOrsis has been attacked as a warning to us.  We must move quickly to offer our brethren what aid we can.\n\nMeet with Nadun at the Arsad Trade Post outside of Mar'at.  I will begin preparations to take care of the displaced and wounded.", sourceObjective = "Speak to Prince Nadun at the Arsad Trade Post outside Mar'at in Uldum.", completion = "Do you see what Deathwing's minions have done?  Great Orsis is now all but buried in the sand!", sourceObjectiveStatus = "unverified-source-field" }
quests[28136] = { id = 28136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind You!", description = "The three leaders of the Bulwark are powerful and not to be underestimated, {name}. Fortunately for us, you now have a disguise to make you look like one of the Twilight cultists.\n\nYou should put the disguise on and speak with Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion each alone. Get them to turn their backs on you, and when they do, strike quickly!", sourceObjective = "Assassinate Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion.", completion = "Now that those three are dealt with, the combined forces from Freewind Post should be able to handle the rest of the cultists here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28137] = { id = 28137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", sourceObjective = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side.", progress = "Were you able to pull off the heist and get us some fish?", completion = "These fish will do nicely, {name}.  Keeping the troops fed and in good condition is our number one priority and you really came through for us here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28138] = { id = 28138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Human Infestation", description = "This mine was once the heart of Alliance mining operations in Hillsbrad. It now serves as a breeding ground for our loyal spiders, though, the humans still occupy it - in a way.\n\n<Keyton grins.>\n\nBut onto business! Warden Stillwater has called for more workers at the Sludge Fields. I want you to enter the mine with these shackles and capture Hillsbrad humans for labor in the fields.\n\nBreak them out of their web paralysis and beat them into submission before you use the shackles.", sourceObjective = "Capture 8 Hillsbrad Humans.", completion = "These will do nicely. I do wonder what the warden has planned for them. Last I heard the Sludge Fields were overrun by some very bad things.", sourceObjectiveStatus = "unverified-source-field" }
quests[28139] = { id = 28139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Codemaster's Code", description = "{name}, the bonds holding Magatha are specially encoded. She can only be released if we get those codes.\n\nThere's a device near Codemaster Deethuk in the Bulwark to the southeast. It contains the codes.\n\nPlease obtain them.", sourceObjective = "Obtain the Codemaster's Code.", progress = "Do you have the codes to the Elder Crone's bonds?", completion = "Good. Now there's only one thing left to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28140] = { id = 28140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder Crone", description = "You have the code. Now all you have to do is head to the eastern section of the Bulwark and free the Elder Crone.\n\nGood luck, {name}. Thank you for all you've done.", sourceObjective = "Disable Magatha's Bonds Controller.", sourceObjectiveStatus = "unverified-source-field" }
quests[28141] = { id = 28141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Sun King", description = "The Seal of the Sun King serves as a defense mechanism for Ramkahen.\n\nWhen the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders.\n\nThey attacked this holy site on their way west and robbed it of the relics which once provided its power.\n\nRecover the relics for us.  Without them we are powerless to defend against attacks from the desert.", sourceObjective = "Obtain 4 Relics of the Sun King.", progress = "Did you succeed?", completion = "Thank you.  The rumors I'd heard about you are proving true after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[28142] = { id = 28142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Withering", description = "According to Magatha, she'll meet you just outside of the Twilight Withering to the east.", sourceObjective = "Speak with Magatha Grimtotem at the Twilight Withering in Thousand Needles.", completion = "It took you long enough. Do you think that we are playing games here?", sourceObjectiveStatus = "unverified-source-field" }
quests[28143] = { id = 28143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Withering", description = "You should not keep the Elder Crone waiting, {name}.\n\nShe said that she'd be up top and just outside of the Twilight Withering to the east.", sourceObjective = "Speak with Magatha Grimtotem at the Twilight Withering in Thousand Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[28144] = { id = 28144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Little Monsters!", description = "The long stretch of coastline directly south of our position that extends from west to east is known as the Western Strand. Along the Western Strand you will find two things: murlocs and our stolen \"supplies.\"\n\n<Keyton puts his hands in the air and makes quotation marks with his fingers.>\n\nThose damned thieving murlocs struck while our backs were turned and took our \"supplies.\"\n\nSarus and I cannot leave this post. We need you to head to the Western Strand and recover those \"supplies!\"", sourceObjective = "Recover 6 Forsaken Camp \"Supplies.\"", progress = "Recover our \"supplies,\" {name}!", completion = "At least we'll be prepared for any future incidents. Moving \"supplies\" like this around is a risky proposition. You never know who is going to open their big fat mouth.\n\n<Keyton raises what appears to be an eyebrow at you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28145] = { id = 28145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomblood Antidote", description = "Iset attempted to defend this holy ground when the Wastewander bandits ransacked it.\n\nThey appear to have used the potent toxin present in the venomblood scorpids.\n\nTake this vial and collect venom from their corpses so that I may concoct an antidote.  I fear Iset might not have much time.", sourceObjective = "Fill the Antidote Vial with the the poison of 8 Venomblood Scorpid corpses.", progress = "Did you obtain it, {name}?", completion = "Thank you, {name}.  We might yet save Iset.", sourceObjectiveStatus = "unverified-source-field" }
quests[28146] = { id = 28146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coastal Delicacies!", description = "My spiders are hungry and agitated! They haven't eaten for days and are starting to sample our human captives. We can't have that. We need those humans for use in the Sludge Fields.\n\nI want you to take one of my hungry mine spiders out and feed it murlocs from the Western Strand, south of here. Whatever you kill, it'll eat! The more the better!", sourceObjective = "Feed the Hungry Mine Spider 12 Murlocs from the Western Strand.", completion = "This should keep it happy and content for a few days. You've done a good thing here, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28147] = { id = 28147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purple is Your Color", description = "So far as I can tell, the Glopgut Ogres right outside the cave here have not yet joined up with the Twilight's Hammer. If we're clever, we can turn the two groups against each other.\n\nLet's roll with a little trick I learned in Silithus. First we'll need to put together a set of cultist robes for you.\n\nHead south of here and kill some Twilight Windwarpers in the Twilight Breach. Aside from disrupting whatever they're up to, it'll give you a chance to collect garment scraps.", sourceObjective = "Gather up 8 Twilight Garment Scraps.", progress = "This is good, {name}. With heroes like you stirring up trouble out here, we'll keep the cult distracted from our main invasion.\n\nDo you have a disguise?", completion = "What did you manage to get? I suppose we can piece something together from this.\n\nAfter all, you're not joining the cult. We just need to fool a few ogres.", sourceObjectiveStatus = "unverified-source-field" }
quests[28148] = { id = 28148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Corrupted", description = "The sickening corruption of demons pervades this entire forest. The soil, the trees, the animals... all grow thick with fel magics.\n\nWe of the Emerald Circle have sworn to cleanse this forest, and doing so requires a constant battle. While some life here can still be healed, the bears and wolves that wander nearby have been twisted too far.\n\nWe must end their suffering, and ensure their bodies do not spread the taint further. Hunt the bears and wolves, and return to me with their hides.", sourceObjective = "Collect 10 Corrupted Pelts from Angerclaw Bears or Felpaw Wolves.", progress = "I must have the pelts to purge them of the leftover demon essence.", completion = "I will see these are burned swiftly and safely, {name}. You have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28149] = { id = 28149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers in the Wind", description = "You hear dem, {class}? De voices from de cave. Dey want to talk, but dey ain't got no breath.\n\nLet's find a way to listen. De Twilight's Hammer, dey talk to de wind. Go to de Twilight Breach south of here, and grab de Windspeaker Charm from de camp. It'll be atop a stone pillar.\n\nWe'll need us de breath of the elementals, too! Slay de Storm Vortexes and take what joo need.", sourceObjective = "Collect a Windspeaker charm and 5 Breath of the Vortex.", progress = "Shhh, {name}! Listen. Listen...", completion = "Dat's de stuff, mon!\n\nNow can you hear dem? De spirits, dey be talkin', but dey say nothing nice.\n\nLet us bring dem to de light.", sourceObjectiveStatus = "unverified-source-field" }
quests[28150] = { id = 28150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Arcane Ally", description = "The Emerald Circle is sworn to accept the help of any who wish to fight the demons of Felwood. Though my people have long shunned the arcane, we cannot afford to deny ourselves such advantage here.\n\nArcanist Delaris, a surviving Highborne mage, helps us battle the Jadefire satyr. Follow the road to the north, and you will find her at our encampment overlooking the Ruins of Constellas.\n\nIf you wish to help cleanse Felwood, follow her requests as you have mine.", sourceObjective = "Speak with Arcanist Delaris at the Ruins of Constellas.", completion = "There is little time for talk, {class}. The druids fight valiantly against the satyr, but fel sorcery blocks their path.\n\nLuckily, I have a plan...", sourceObjectiveStatus = "unverified-source-field" }
quests[28151] = { id = 28151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressed to Kill", description = "Your disguise is ready, {name}. Whenever you go north into Glopgut's Hollow now, your Twilight's Hammer regalia will fool the ogres.\n\nThe rest of the plan is simple: you kill a bunch of Glopgut ogres, and they blame the cult. Are you ready to create some havoc in the ogre camp? I thought so.", sourceObjective = "Kill 10 Glopgut Ogres. Your Twilight's Hammer disguise will automatically apply while inside Glopgut's Hollow.", completion = "Hah! I'm sure Twilight's Hammer wanted to number those ogres among their ranks. Now they'll probably have to fight them off instead.\n\nThis is good, {name}. With one well-placed {class} we managed to do the work of a small army. I'll let Warlord Krogg know of your work here!", sourceObjectiveStatus = "unverified-source-field" }
quests[28152] = { id = 28152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaedenar Awaits", description = "The cultists you saw guarding the claw were members of the Shadow Council, foul warlocks behind nearly every attempt to bring demons into Azeroth.\n\nNorth of here is Jaedenar, named in worship of Kil'Jaeden himself. Deep beneath it stretches Shadow Hold, a former barrow den and the Shadow Council's own stronghold on Azeroth.\n\nTake these herbs north to Wildheart Point, on the east side of the road. Greta Mosshoof will need them for her plan to purify Shadow Hold for good.", sourceObjective = "Deliver the Arcanist's Herbs to Greta Mosshoof at Wildheart Point.", progress = "Greetings, {class}. What brings you here?", completion = "Ah, just what I was expecting. With these herbs, our preparations for Jaedenar are nearly ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[28153] = { id = 28153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Lord Fel'dan", description = "Shadow Lord Fel'dan awaits further in the depths, {name}.\n\nHis wrath will be unmatched now that you have slain his beloved pets. Even without Moora and Salia at his side, he is a terrible force to be reckoned with.\n\nBeware his dark powers; he is nearly more demon than orc by now.", sourceObjective = "Slay Shadow Lord Fel'dan.", completion = "The Shadow Council is broken! One task remains...", sourceObjectiveStatus = "unverified-source-field" }
quests[28154] = { id = 28154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muckgill's Flipper or Something...", description = "This looks like Muckgill's flipper or something. Maybe there's somebody that cares that you killed this murloc back at the Azurelode Mine camp. Probably not, but it's worth a shot.\n\nTake Muckgill's fin or whatever it might be back to Captain Keyton at the Azurelode Mine in southwestern Hillsbrad.", sourceObjective = "Deliver Muckgill's Flipper back to Captain Keyton at the Azurelode Mine in Hillsbrad Foothills.", progress = "Do I look like some kind of murloc scientist?", completion = "Muckgill you say? Never heard of him. What is this anyway? Some kind of fin or something?", sourceObjectiveStatus = "unverified-source-field" }
quests[28155] = { id = 28155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Banehollow", description = "Only one final power remains lurking in the depths of Shadow Hold now: Lord Banehollow.\n\nThe Shadow Council here serves his whims, and even Fel'dan was a mere instrument for him to prepare this land for another invasion of the Burning Legion.\n\nProceed carefully, {name}. A dreadlord is a terrifying foe. Stand tall and triumph!", sourceObjective = "Slay Lord Banehollow.", completion = "Truly incredible, {name}. To journey within the very lair of evil here and slay every fiend that stands before you... I am overwhelmed.\n\nThe Emerald Circle thanks you for your work here in Felwood. As for Andalar, we will send scouts to rescue him at once. He shall have a hero's welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[28156] = { id = 28156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Mine Rescue", description = "<You can hear Dumass speaking through the webbing.>\n\nHI! SPIDERS EVERYWHERE! THE CAPTAIN SENT ME TO SAVE THE WORLD AND CAPTURE HUMANS! WHAT IS THIS PLACE ANYWAY? IT'S SO HOT! I...\n\n<Dumass goes on and on about his situation.>\n\nPerhaps you should cut him free and get him back to safety. Or you can just leave him here, though it's your fault that he's stuck in this mine.", sourceObjective = "Escort Dumass to Safety!", progress = "Do I look like some kind of baby sitter?", completion = "Have you ever heard the saying \"survival of the fittest?\" What you're doing conflicts with natural law, buddy! This idiot should have died in the mines. There's no telling what kind of harm he'll cause to himself or another person now that you've saved him from his inevitable demise.\n\nAnd you know who's fault that'll be, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[28157] = { id = 28157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Twilight Elements", description = "The Twilight's Hammer have summoned a monstrosity. It's a combination of the four elements infused with the power of their special ore, Elementium.\n\nIf you want to save your precious Thousand Needles from total destruction, you're going to have to destroy it. But first, you'll need a few things to get through its protective shielding.\n\nGo east into the Withering and bring back the four Twilight elements.", sourceObjective = "Collect the four Twilight Elements: Air, Earth, Fire, and Water.", progress = "Do you have all of the elements, {class}?", completion = "<Magatha gazes at you with naked disdain.>\n\nI'll combine them into a suitable form. I'll keep its use simple.", sourceObjectiveStatus = "unverified-source-field" }
quests[28158] = { id = 28158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound", description = "There are two very powerful elementals that the Twilight's Hammer have bound. They are using the bound Fury and Vortex to infuse Animus with a great deal of power.\n\nWhen Animus has absorbed enough of their power, he will explode. The rest of Thousand Needles and much of the surrounding lands, will be obliterated.", sourceObjective = "Unbind the Bound Fury and the Bound Vortex.", completion = "A simple task for a simple boy. Let us see if you have what it takes to finish the job.", sourceObjectiveStatus = "unverified-source-field" }
quests[28159] = { id = 28159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doomstone", description = "At the core of Animus is an artifact known as the Doomstone. One of its properties is an ability to absorb a great deal of energy.\n\nThis is how the cultists are trying to set off the explosion... by overloading the stone and amplifying the power through the elemental.\n\nBring me the Doomstone. For safe keeping, of course.", sourceObjective = "Collect the Doomstone.", progress = "Do you have the Doomstone, {class}?", completion = "Surprising... you lived.\n\nI thank you for doing my dirty work, {class}. You kept my hands clean while ridding me of some incompetent Grimtotem leaders.\n\nNot only do I have the Rattle of Bones, the Writ of History, and the Drums of War, but I now have the ultimate artifact: the Doomstone!", sourceObjectiveStatus = "unverified-source-field" }
quests[28160] = { id = 28160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if we ever cross paths again, you will die.", sourceObjective = "Speak with Fizzle Brassbolts on Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "Wow, she's evil! But, what does it mean, {name}? Is Magatha going to destroy us? Is she in charge of the Twilight's Hammer now?\n\nWhatever happens, you've delivered us from our enemies. Please allow me to show you our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28161] = { id = 28161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if ever we cross paths again, you will die.", sourceObjective = "Speak with Pozzik on Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "Wow, she's evil! But, what does it mean, {name}? Is Magatha going to destroy us? Is she in charge of the Twilight's Hammer now?\n\nWhatever happens, you've delivered us from our enemies. Please allow me to show you our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28162] = { id = 28162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", sourceObjective = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad. The crocolisks can be found in the swamp, just west of Baradin Hold.", progress = "You cleared out that swamp yet?", completion = "Looks like you were able to get the croc hides that we needed.  Thanks {name}, your contributions will not go unnoticed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28163] = { id = 28163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the horde scum but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any horde that you find.\n\nYou know what they say, the only good horde is a dead horde!", sourceObjective = "You have been instructed to kill 12 Horde Infantry on Tol Barad. You can find the holdouts in The Slagworks, Warden's Vigil and the Ironclad Garrison, here on Tol Barad.", completion = "Those filthy horde never stood a chance.  Nice work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28164] = { id = 28164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Brother Silverhallow", description = "I just received word that you are needed in Orgrimmar, {name}. Brother Silverhallow has asked for you to return to the city as quickly as you are able. His message didn't include any other information, and the matter seemed urgent.\n\nLook for Brother Silverhallow in the Goblin Slums of Orgrimmar.", sourceObjective = "Speak with Brother Silverhallow in the Goblin Slums of Orgrimmar.", completion = "I'm glad to see you received my message.", sourceObjectiveStatus = "unverified-source-field" }
quests[28165] = { id = 28165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Horde we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", sourceObjective = "You have been instructed to kill 10 demons of any type in the D-Block, just northwest of Baradin Hold.", completion = "D-Block is all clear?  Good work, {name}.  We will send down a crew to start cleaning up right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[28166] = { id = 28166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thog's Nightlight", description = "To see de spirits, we need a special light. A light that lights up one's insides. De light of souls.\n\nTwilight's Hammer uses dem to root out traitors after what we did to dem in Hyjal. Dey just gave one to de Glopgut ogres as a gift.\n\nInside de Glopgut Hollow to de north, you'll find de great big brute Thog. He's got him a Light of Souls. At least, he will until you take it from him.", sourceObjective = "Get the Light of Souls from Glopgut's Hollow.", progress = "De light of souls. Does you have it, mon?", completion = "Ah, dis be it, mon.\n\n<The lens glows brightly in Buunu's hands, casting unearthly rays of light across the shadowy cave mouth.>\n\nWe be ready to bring dem spirits out de shadows now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28167] = { id = 28167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Carvo Blastbolt", description = "I'm going to start preparing my men to leave this place. We can't hold out here any longer. I want you to move to a forward position in the middle of the large room ahead.\n\nYou should find Carvo Blastbolt there. He'll give you further instructions. Good luck, {name}, and I'll see you on the surface.", sourceObjective = "Report to Carvo Blastbolt in Gnomeregan.", completion = "Did Nevin send you ahead? That means he's getting ready to end the mission, but there are still survivors to be rescued. We have to help them!", sourceObjectiveStatus = "unverified-source-field" }
quests[28168] = { id = 28168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Sludge Fields", description = "Warden Stillwater, over at the Sludge Fields, north of here, has sent out a distress signal. The missive wasn't clear, but from what I could make of the letter there's a riot happening at the Sludge Fields and most of the guards have been killed. The warden has warned that any would-be-heroes approach from the back entry, located on the western side of the Sludge Fields.\n\nHe's also asked for discretion. He doesn't want news of this little *ahem* uprising to surface.", sourceObjective = "Report to Warden Stillwater at the Sludge Fields in Hillsbrad Foothills.", completion = "Who are you? Did Sylvanas send you? Everything is FINE! Yes, perfectly fine! I've got it all under control!\n\nWell, fine all things considered that is... We've got a few problems that perhaps you could help with, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28169] = { id = 28169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withdraw to the Loading Room!", description = "Excellent job gathering the other survivors! They - and you - are the reason S.A.F.E. teams keep coming down here. Nevin won't rest until we've found and rescued every possible survivor.\n\nI'm sending my men to the Loading Room to prepare for decontamination. Please follow them and meet up with Gaffer Coilspring when you arrive. She'll set you up for decontamination and have you on your way to the surface.", sourceObjective = "Follow the S.A.F.E. Operatives to Gaffer Coilspring in the Loading Room.", completion = "It's good to meet you, {class}. We rarely come across survivors as strong and capable as you are. I can help get you decontaminated and on your way out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28170] = { id = 28170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Terrors", description = "Me friend Uchek is in de cave already. We set up three shrines inside. All you gotta do is flush out de bad juju from each one, mon.\n\nGo inside de cave here and talk to Uchek. He put you in a trance, put you in de spirit realm. Tread carefully! If you see a ghostly beast, you don't be panicking. Shine de Light of Souls on de beast for a moment or two, and de light will send 'em away for good. De light will keep you safe. Now go cleanse de three shrines!", sourceObjective = "Talk to Uchek in The Gullet. From the spirit realm, use your Light of Souls to keep yourself safe while you visit the three shrines inside the cave.", progress = "Don't fear de darkness, mon.", completion = "You see! De dead be nothing to be scared of. You brought de light to de darkness, mon, and never flinched.\n\nWe can use dis cave now as a base of operations in de northern Highlands. You're de best, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28171] = { id = 28171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And the Sky Streaked Red", description = "With Deathwing otherwise occupied, we have a grim and daunting task ahead of us, under charge of the queen herself. The black dragonflight is to be wiped out.\n\nI would welcome your aid in this, if it is offered. As soon as you are ready, I will send you with the next flight joining the attack.", sourceObjective = "Join the assault on the black dragonflight.", completion = "It seems you are still with us. I'm somewhat appreciative of that.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28172] = { id = 28172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Done Nothing Wrong", description = "The Blackrock orcs of the steppes serve a dark master -  one who performs twisted experiments on living creatures to create his own menagerie of abominations.  Many of his test subjects are as corrupted as their master, but others are completely innocent.\n\nIn the whelping downs to the south, they chain baby dragons to the ground, preparing them for such experiments.  I will not stand for this.  Break their fetters and return the hatchlings to me... to safety.", sourceObjective = "Obtain a Freed Red Whelpling, a Freed Green Whelpling, a Freed Blue Whelpling, and a Freed Bronze Whelpling.", progress = "I hope we weren't too late.", completion = "I will see to it that these dragons are taken care of.", sourceObjectiveStatus = "unverified-source-field" }
quests[28173] = { id = 28173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackout", description = "The Twilight Drakehunters used vicious implements to drag our circling drakes from the sky. Hooks that buried into their scales and held the Twilight secure while they brought our kin to the ground.\n\nWe are past the point of peace. Past hope for their redemption. The only mercy we have left to offer the black flight is the oblivion that they so passionately pursue.\n\nUse these hooks to slay the Obsidian Pyrewings to the south. They should allow you much maneuverability in the air if used right.", sourceObjective = "Slay 8 Obsidian Pyrewings after using the Wyrmhunter Hooks to reach them.", completion = "You seem to have made use of the disturbing implements with ease.\n\nI take solace in knowing that some tools of evil can ultimately still lead to safeguarding life. Nothing is without purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[28174] = { id = 28174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Vengeance", description = "The Blackrock orcs are ceaseless.  They swarm atop the battle-plains to the east, poised to strike at any moment.\n\nThey already attacked my homeland once.  I'm here to make sure it doesn't happen again.\n\nIf you hold any love for mankind, you'll do the same.  So prove yourself.  Travel south, to the Whelping Downs, and slay their whelpers and the hatchling black dragons.  Prove to me that you're ready for this war.", sourceObjective = "Slay 5 Blackrock Whelpers and 5 Flamescale Broodlings.", progress = "I suppose you don't have what it takes.\n\nThat's fine.  I can fight this war myself.", completion = "So you're in, then?\n\nGood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28175] = { id = 28175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shining Through the Dark", description = "The great petrified tree that lies before us to the south was once a beacon of great life. Our beacon. We lost this forest to the black flight, and it has since been corrupted and petrified. Nearly unredeemable.\n\nBut all is not without hope. I've brought a powerful tool to begin the healing process. The tree may still be saved, with much time and fortune, and with perhaps a little effort from you.\n\nBring this, Alexstrasza's Tear, and use it within the hollowed heart of the tree.", sourceObjective = "Use Alexstrasza's Tear within the hollow beneath the Obsidian Tree.", progress = "The black flight may never be redeemed, but in the wake of all of their destruction, there is always hope for life anew.", completion = "You've started a wonderful thing this day, amidst all of this blood shed.\n\nIt may take many years, but this ravaged land will be restored. It will be beautiful again.", sourceObjectiveStatus = "unverified-source-field" }
quests[28176] = { id = 28176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Young Home", description = "In the southwestern portion of the Obsidian Forest, you will find some of the black egg clutches. Many of the eggs can be hatched at any time with a bit of prodding from the right flame, and as the whelplings hatch, they will cry out and flock for their mother.\n\nDo not worry, if this purging is to be taken to the whelps, that is not a task that I will force on you. I simply want you to let them out and follow them home as they seek their mother. It is she who we must confront.", sourceObjective = "Use the Mother's Flame on Obsidian Eggs to release whelps. Follow those hatchlings to the lair of their mother.", progress = "No black dragon capable of breeding can be left alive.", completion = "Lirastraza sent me ahead to the lair, suspecting the black dragon we are seeking may still be here. Judging by the hatchlings, it seems she was not mistaken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28177] = { id = 28177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "If we're going to wage war against the Blackrock clan, we're going to need to plan ahead.  My colonel has already put the plan together - now it's time to execute.\n\nI need scorpid stingers... the sharpest ones you can find.  Scorpids are all over the steppes, but you can find most of them in the gulch to the west.\n\nDon't worry about what they're for.  You'll find out soon enough.", sourceObjective = "Obtain 5 Razor-Sharp Scorpid Barbs.", progress = "Back already?", completion = "Those scorpids are easy to underestimate.  You're lucky you didn't end up on the end of one of these barbs.  Or maybe you're just good.\n\nI'll add these to the stockpile.  We're not done yet, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28178] = { id = 28178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Future Project", description = "We'll need worg hides, and lots of them.  It doesn't matter if they're torn, burned, or bloody, but we need plenty of them.\n\nActually, it's probably better if they're a little beat-up.\n\nYou'll find worgs both to the west and to the east of here.", sourceObjective = "Obtain 11 Ember Worg Hides.", progress = "Let's take a look at those hides.", completion = "Believe me, {name}... I'm just as anxious to get to the killing as you are.  We've got to keep to the plan.  The armageddon will come soon enough.\n\nI'll keep these hides here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28179] = { id = 28179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mud Hunter", description = "Hope you're not afraid of getting dirty.  Judging by the looks of you, that won't be a problem.\n\nTo the north, at the lava's edge, you'll find piles of dark mud.  I need it.\n\nIt'd be best if you didn't ask questions, and focused your efforts on following orders, {name}.", sourceObjective = "Obtain 9 piles of Obsidian-Flecked Mud.", progress = "You'll want to watch out for those obsidian elementals.  They have a tendency to sneak up on you.", completion = "This is exactly what we need.\n\nDon't worry, {name}... the orc-killing will come soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[28180] = { id = 28180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sand, the Cider, and the Orb", description = "Colonel Troteman is waiting for us to the east.  Before we head out though, we need to gather some more stuff.  This time, you'll be taking it from a warlock by the name of Gorzeeki Wildeyes.\n\nYou'll probably find him to the northwest, near the Altar of Storms.  Tell him he's going to help us out.  We need the sand, the cider, and the orb.\n\nHe'll know what it means.", sourceObjective = "Speak with Gorzeeki Wildeyes near the Altar of Storms.", completion = "Gah!  Who are you?\n\nOh, so Keeshan sent you?  Good.  Would ya mind sticking around for a while?  It's nothing big... I just need you to kill some warlocks for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[28181] = { id = 28181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlocks Have the Neatest Stuff", description = "Keeshan said he needs supplies?  I've got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they're not letting me back in.\n\n<Gorzeeki sizes you up.>\n\nYou might be able to get in, though.  Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb.  I'm pretty sure that's what he wants.\n\nOh, and if you happen to accidentally kill any of those orcs while you're up there, I wouldn't be terribly upset.", sourceObjective = "Obtain a handful of Slumber Sand, a jug of Fel Slider Cider, and a Clear Glass Orb.", progress = "Let's see if you managed to get everything.", completion = "I hope that's what Keeshan was looking for.  It's not doing me much good right now, anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[28182] = { id = 28182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Boxing", description = "Ner'gosh the Shadow is the leader of those warlocks to our north.  He's the jerk that kicked me out of my home once those Blackrock orcs started showing up.  Well, they're all jerks, but he's the jerkiest.\n\nIf I'm ever going to move back in near the Altar, Ner'gosh has to go.", sourceObjective = "Slay Ner'gosh the Shadow.", completion = "Knowing the way those orcs operate, there'll be another one to take his place soon.  I'll see if I can't sneak back into the altar before that happens.\n\nThanks, buddy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28183] = { id = 28183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Keeshan", description = "Well I suppose I'm done with you here.  I'll go shoo those other warlocks out when I build up the courage.\n\nHere, don't forget those supplies.", sourceObjective = "Bring the Warlock's Supplies back to John J. Keeshan at Flamestar Post in Burning Steppes.", progress = "It looks like you managed to deal with Gorzeeki.", completion = "<Keeshan looks through the crate.>\n\nGood, good, good.  We can move on.  Our war takes us east, away from Blackrock Mountain... for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28184] = { id = 28184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiselgrip, the Heart of the Steppes", description = "We're headed to Chiselgrip, right in the center of these steppes.  We'll rendezvous with the Thorium Brotherhood there, as well as with Troteman.\n\nYou familiar with the Brotherhood?  Those dark iron dwarves have helped me out more than once.  We may need their help again.\n\nWe'll pass through Black Tooth Hovel on our way there.  What do you say we kill a few orcs while we travel?  I'm getting a little restless here in this camp.", sourceObjective = "Kill any 15 Blackrock troops on your way to Chiselgrip.", completion = "You'll have to excuse me, but we're not taking visitors right now.  I'll ask you to leave Chiselgrip out the same door you came in.\n\nOh, Keeshan... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28185] = { id = 28185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Excellent work on the island capture, {class}.  Now that we have claimed the island, we need to make these cellblocks useable for prisoners.  D-Block has been especially hard to clear out.  Unfortunately it has become overrun with demons of all sorts.\n\nWe have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there.  I need you to kill him and bring back his collar.", sourceObjective = "You must kill Svarnos in the D-Block and return with his Cursed Collar. Svarnos can be found in the D-Block, just northwest of Baradin Hold.", progress = "Is the core hound dead?", completion = "Svarnos is finally dead?  Looks like we can finally get to work setting up that cellblock then.  Thank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28186] = { id = 28186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Shackles", description = "Have you been down in the D-Block yet, {name}?  Every time we clear that infested cellblock out, the demons seem to return rather quickly.  We learned that they regenerate from the cursed shackles scattered around the area.  That's where you come in to the picture {name}.\n\nI need you to retrieve as many of those shackles as you can and bring them back to me.  We will destroy them immediately.", sourceObjective = "You have been asked to recover 8 Cursed Shackles from the D-Block, just northwest of Baradin Hold.", progress = "Did you find many shackles?  Reports mentioned that they were all over the place down there.", completion = "The shackles!  We will begin the process of destroying these shackles immediately {name}.  Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28187] = { id = 28187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missed Me By Zhat Much!", description = "Okay, {race}! Zhis just got real!\n\nSomevone zhinks zhat zhey can get rid of me zhat easily, hmm?\n\nVe shall see about zhat! Nozhink can shtop zhis vork! Nozhink!\n\n<Schnottz looks around at the encroaching flames.>\n\nVe should probably get out of here.\n\nHuury up! Time is vastink!", sourceObjective = "Speak to Commander Schnottz when you are ready to accompany him out of the burning building.", completion = "It is times like zhese, zhat one learns who his friends really are...", sourceObjectiveStatus = "unverified-source-field" }
quests[28188] = { id = 28188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Revolt", description = "We have the island, now we need to put the resources here to work.  We found an abandoned cellblock just southwest of here and we need you to go check it out {name}.\n\nReports have come back that it is overrun with prisoners that have been stuck down there for years.  Do whatever you need to do to clear that place out.  Report back to me when you are done.", sourceObjective = "You have been instructed to kill 10 prisoners of any type in The Hole, just southwest of Baradin Hold.", completion = "You cleared that area out?  Looks like you might be more useful to us that we thought, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28189] = { id = 28189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Right Thing", description = "You have come upon a horrific scene. Someone or something has buried all of the humans up to their necks in a manner consistent with planting. The ghouls, which are seemingly tending the field of human seedlings, periodically jump to the nearest human and devour its head!\n\nYou can end this right here and now. Take this shovel and \"save\" the humans.\n\nDo the right thing.", sourceObjective = "\"Save\" 15 Human Seedlings.", sourceObjectiveStatus = "unverified-source-field" }
quests[28190] = { id = 28190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tainted Ooze", description = "This all started with Winna Hazzard. She was a forsaken apothecary at Bloodvenom Post, researching ways to use the demonic ooze here against the Alliance.\n\nWe warned her she was going too far, but she didn't listen, and we did not act fast enough. Now her and everyone at Bloodvenom Post are nothing more than mindless slime creatures...\n\nThe disgusting oozes she used for this still roam near the pools to the east and south. I beg you, {class}, destroy them so that others cannot commit such evil.", sourceObjective = "Slay 8 Tainted Oozes.", progress = "The very thought of those disgusting creatures sickens me! Urgh...", completion = "My rage quells at the news... perhaps I will find it easier to rest and heal now.\n\nMaybe my stomach will settle as well. Urgh...", sourceObjectiveStatus = "unverified-source-field" }
quests[28191] = { id = 28191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting End", description = "The Obsidian wyrmkin litter the landscape to our south. They're in no position to push back against us, but one can never tell what new threats the ebb of battle may bring.\n\nI want you to take the fight to the wyrmkin. Clear them out so that we may proceed with purging this land of the polluting presence of the black dragonflight.", sourceObjective = "Kill 10 Obsidian wyrmkin.", completion = "You've proven a great ally. I would have never expected such upon our first meeting.", sourceObjectiveStatus = "unverified-source-field" }
quests[28192] = { id = 28192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One Here Gets Out Alive", description = "This farm is under lockdown! Nothing gets in and nothing gets out! We're still assessing the situation to try and figure out exactly what happened, but my theory is that the laborers ate the mushrooms and somehow mutated into hideous undead monsters. I mean, how else could this have happened? This is just a farm! We grow mushrooms here! And sludge! Yes, sludge!\n\nTake a look around, {class}, because now that you're here you can't leave until this issue is resolved.\n\nSee for yourself!", sourceObjective = "Assess the situation at the Sludge Fields.", completion = "As you can see, they're all monsters! Most of my guards died and the ones that managed to escape are now holding down the barricades, preventing any of these potentially dangerous creatures from getting out.\n\nWe need your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[28193] = { id = 28193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockdown!", description = "Zhat buildink did not explode by itself!\n\nSomevone is tryink to do me in, and you von't rest until I find out who!\n\nShtaht vizh zhe guests. Visit vizh zhem, observe zheir demeanor, and zhen report back to me.\n\nIf zhey know anyzhink at all, I vill haff zhem interrogated!\n\nDismissed!", sourceObjective = "Commander Schnottz wants you to observe the guests in Schnottz's Landing.", progress = "Vell, {race}?\n\nVere zhe guests involved in zhe plot to haf me rubbed out?", completion = "Zhey know nozhink, you say?\n\nVery vell, zhen. Zhe search goes on...", sourceObjectiveStatus = "unverified-source-field" }
quests[28194] = { id = 28194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Escape", description = "Please, {class}! We need your help!\n\nWe're being kept in this building against our will. And with the commander on such a tirade, there's no telling what he might do to us!\n\nPerhaps if you were to secure some uniforms for us, we could sneak away.\n\nWe never should have come here. I see that now.\n\nIf you help us escape, I will write the TRUTH of what has happened here.\n\nThe men on those ships are all dressed in the garb we need.", sourceObjective = "The Prolific Writer in Schnottz's Landing wants you to collect 6 Fresh Uniforms from Schnottz Sea Sailors.", progress = "Were you able to find us some uniforms, {race}?", completion = "These are perfect, {class}.\n\nWish us luck!", sourceObjectiveStatus = "unverified-source-field" }
quests[28195] = { id = 28195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending a Message", description = "I haf eyes and ears in every corner of zhis region, {race}.\n\nI haf heard of zhe murmurings zhat go on amonkst my troops. I haf been most tolerant of zhis pathetic behavior - until now!\n\nI vill send zhe message to everyvone in my ranks, zhat dissension vill not be tolerated!\n\nYou are to exterminate zhe captains aboard my ships in dock. Zhey haf been amonk zhe most disgruntled.\n\nVhen zhis has been done, I vill monitor zhe communications and determine vhat to do next.\n\nDismissed!", sourceObjective = "Commander Schnottz wants you to kill Captain Margun, Captain Cork, and Captain Kronkh", completion = "Very good, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[28196] = { id = 28196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Hillsbrad", description = "The journal documents the last 62 days of Clerk Horrace Whitesteed's life. In it is written damning allegations against Warden Stillwater and his activities at the Sludge Fields.\n\nYou should show this to the warden. He will undoubtedly have an explanation for what is written in this journal.", sourceObjective = "Deliver the Battle for Hillsbrad to Warden Stillwater at the Sludge Fields in Hillsbrad Foothills.", progress = "What's this?", completion = "<Warden Stillwater flips through the journal, reading under his breath.>\n\nRamblings of a mad man! Clearly he had been ingesting the mushrooms. It is good that you brought this to me, {name}. I will burn it myself!", sourceObjectiveStatus = "unverified-source-field" }
quests[28197] = { id = 28197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "We must destroy all of the evidence, {name}! Did I say evidence? I meant crazed undead! Anyway, discretion is key. We must not let the rampaging undead make it out of the Sludge Fields and no one outside of this institution must know about what happened here!\n\nDirectly southeast of here in what used to be the old mushroom farm you'll find a reanimated fiend known as Citizen Wilkes and his cohort, Clerk Horrace Whitesteed. They have been causing huge problems for my guards. Find them and kill them!", sourceObjective = "Kill Citizen Wilkes and Clerk Horrace Whitesteed.", progress = "Kill the beasts! We can't have a rampaging geist and skeleton wandering the countryside!", completion = "Well done! Wilkes was hanged after we discovered that he was ingesting mass quantities of mushrooms and other highly toxic substances. After he died he awoke, reborn as an undead geist. Many of my guards fell to Wilkes before he ran off into hiding. Fearing something like this might happen again, we incinerated the Clerk until only bones were left!\n\nWhy would they willingly ingest toxic substances? I have no idea! This is a farm, sir, nothing more!", sourceObjectiveStatus = "unverified-source-field" }
quests[28198] = { id = 28198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weakest Link", description = "They say a chain is only as strong as its weakest link.\n\nI subscribe to that theory and expand upon it.\n\nRather than removing that weak link, one must... strengthen it.\n\nThe other links will step up their performance out of fear of they themselves becoming the weakest link.\n\nIn my army's case, our weak link has a name.  Salhet.\n\nYou'll find him training near the bottom of those stairs.\n\nStart him off with something easy.  The hyenas on the hills to the west, perhaps.", sourceObjective = "Speak to Salhet at the Ramkahen Legion Outpost in Uldum.", completion = "It is a great honor to meet you, {name}!  I've heard much about you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28199] = { id = 28199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Science!", description = "Samples... yes... must have samples! These, ah, experiments... I mean, these unfortunate laborers must be studied.\n\nTravel southeast to the first farm and kill the risen ghouls. From their decrepit corpses you must recover flesh samples. Bring them to me!\n\n<Arnauld wrings his hands together and laughs maniacally for no discernible reason.>\n\nMust test!", sourceObjective = "Recover 6 Flesh Samples.", progress = "For science!", completion = "These samples will give us a better understanding of the mindless undead. Take these coins as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[28200] = { id = 28200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Element of Supplies", description = "You'll notice that we're slightly ill prepared for battle.\n\nThe tol'vir tribes had never seen any sort of major confrontation for thousands of years.\n\nAll the combat protocols that the titans programmed into our ancestors are still there, though.  Some are part of our instincts, some get passed on as tradition.\n\nBut none of this can compensate for lack of supplies.  We need weapons.  We need armor.\n\nThe best armor is lined with the skin of the riverbed crocolisks nearby.  Help us gather some.", sourceObjective = "Collect 20 Hardened Crocolisk Hides.", progress = "I am glad to see you don't think you're above this sort of task.", completion = "Excellent job, {name}.  You might not think this adds up to much, but this might very well be the difference between life and death to one of our soldiers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28201] = { id = 28201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ploughshares to Swords", description = "We have a sizeable army, but I'm afraid the coming showdown with the Neferset hordes will demand that all able-bodied tol'vir of Ramkahen and Orsis join in the fight.\n\nI want you to be at the forefront of our recruiting efforts.\n\nGo across the river, to the Akhenet Fields, and recruit the laborers that work there.", sourceObjective = "Recruit 8 Ramkahen Laborers.", progress = "You've returned, {name}.  How are the recruitment efforts faring?", completion = "You are a born leader, {name}.  It'll be good to have you by our side when war comes to these lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[28202] = { id = 28202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an orc.  Their army is made mostly of orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", progress = "We're not done yet, you little {class}!", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28203] = { id = 28203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an ogre.  The firegut ogres have always worked for the Blackrocks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", progress = "We're not done yet, you little {class}!", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28204] = { id = 28204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a goblin.  The Blackrocks have been known to hire goblin mercenaries to fill their ranks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28205] = { id = 28205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a troll.  The Smolderthorn trolls have always worked with the Blackrock orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28206] = { id = 28206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Lad", description = "It was only yesterday that I sent him out to investigate the farm directly east of here, but it feels like an eternity has passed!\n\nTrue perfection. The way his blond locks framed his perfect blood elf face... Such strength. I didn't want to send him away, but he insisted! How could I refuse him?\n\nAlas, poor Johnny Awesome has not returned! I fear the worst, {name}. Find him!", sourceObjective = "Find Johnny Awesome at the Sludge Fields in Hillsbrad Foothills.", completion = "<Johnny is sobbing loudly.>\n\nTw... Twinkles!!!! Th... It killed her!\n\n<Johnny continues to cry>", sourceObjectiveStatus = "unverified-source-field" }
quests[28207] = { id = 28207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slimy Situation", description = "This poor fellow here barely escaped Bloodvenom Post with his life! If we're going to keep him from turning into a slime creature like all the others, we've got to treat the infection.\n\nMushrooms like to grow near the bright green waters around here, like the pond to the east beneath the falls. Most of them are no good... I need you to collect the bright green glowing ones!\n\nIf I have those, I'll be able to whip up something tasty to help this poor tauren. Don't take too long now!", sourceObjective = "Collect 7 Emerald Shimmercaps.", progress = "Remember, it's the bright green glowing ones!", completion = "Most people think the green glow is demonic corruption... but if you've got an eye for shades and hues like me, you can tell it's the energies of the emerald dream! These little guys aren't being corrupted by the waters, they're doing their best to purify it!\n\nNow we'll mash 'em up and make a nice yummy paste for Mr. Tauren to eat and feel all better.", sourceObjectiveStatus = "unverified-source-field" }
quests[28208] = { id = 28208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winna's Kitten", description = "Mr. Tauren here's told me a lot about what happened at Bloodvenom Post. He says Winna Hazzard is still there!\n\nShe's pretty far gone, but what's left of her is making a bunch of new slime. We've got to stop it!\n\nLuckily, I have a plan. Mr. Tauren said Winna used to have a kitten. She fed it corrupted slime water and it ran off into the woods. I saw something lurking to the southeast just past the Bloodvenom Tower, but it sure was bigger than a kitten! Go see if the kitty has a tag...", sourceObjective = "Collect Kitty's Eartag from Winna's Kitten.", progress = "Did you find the kitten?", completion = "Poor little kitty, suffering out there in the woods for so long! You did a good thing for it, {name}. And probably for all the travelers it's been eating.\n\nThis tag will be handy...", sourceObjectiveStatus = "unverified-source-field" }
quests[28209] = { id = 28209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for Lydon", description = "This place is no farm! Stillwater has been experimenting on the humans of Hillsbrad. The monstrosities here are all his creations.\n\nThat's not the worst of it, {class}. The aberrations that have the key to my cage are former Forsaken. Stillwater's experiments have the side effect of turning Forsaken into mindless zombies. Why do you think he's so afraid of letting this get out? He knows that such a crime is punishable by true death.\n\nGet me out of here! The infected sludge guards outside have the key!", sourceObjective = "Recover Lydon's Cage Key.", progress = "Get the key!", completion = "<Lydon takes the key from you.>\n\nI'll let myself out, thanks.\n\nI have never been so angry! Stillwater won't get away with this. I will present his head to the Banshee Queen myself.\n\nYou and I will work together, {name}.\n\nI don't know about this one over here, but I'd prefer he stayed behind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28210] = { id = 28210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaping Up", description = "High Commander Kamses has a special mission for me?\n\nWait... don't tell me.  It's hyenas again, right?\n\nVery well, I shall do my best.\n\nMeet with me at the Sunwatcher's Ridge.\n\nI won't disappoint you.", sourceObjective = "Help Salhet slay 8 Bloodsnarl Hyenas.", progress = "What's the tally?", completion = "Well... that wasn't all that great, was it?", sourceObjectiveStatus = "unverified-source-field" }
quests[28211] = { id = 28211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempered in Elemental Flame", description = "First things first: We're going to need ammunition. Ammunition powerful enough to pierce the armored hide of a black drake. \n\nWest of Thundermar is a Wildhammer town that's been overrun with unbound fire elementals. Any weapons left behind in that conflagration will have been tempered in elemental flame. Tougher than anything I could whip up at this forge!\n\nFind me spears in the Humboldt Conflagration, {name}. The pointier the better.", sourceObjective = "Collect 8 Tempered Spears.", progress = "Spears, yes? My rapid-fire speargun would be rendered ineffective without them.", completion = "Look at that - OW! Pointy! Hot!\n\nThese spears should cut through that dragonhide like an electric cheese-slicing apparatus through butter.", sourceObjectiveStatus = "unverified-source-field" }
quests[28212] = { id = 28212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Stuff", description = "I have a plan to quadruple the recommended torque for a standard speargun of this size, but according to my calculations the act of firing the weapon would shatter the casing. And possibly cleave the planet in two.\n\nI can weld together a chassis 100-times stronger if I had a good source of pure elemental flame for the smelting.\n\nUnbound Emberfiends are roiling around west of here, in the Humboldt Conflagration. Killing them should render them down to pellets of molten fury. Bring me some!", sourceObjective = "Collect 5 pellets of Molten Fury.", progress = "Do you have the molten fury? No no, don't put it in my hand. Here, use the tongs!", completion = "Marvelous! I'll smelt this down into a delicious soup. An angry soup. Of molten metal.", sourceObjectiveStatus = "unverified-source-field" }
quests[28213] = { id = 28213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazzard Disposal", description = "Winna's hooked tight into the source of the slime itself, at the very back of Bloodvenom Post to the west. She makes sure it keeps flowing, and it keeps her safe! But if you can get her attention...\n\nTake the eartag and show it to Winna. If there's even a little, tiny bit of her left, maybe it'll get through. Maybe her regret for her poor lost kitty will come to the surface and she'll feel sorry just one more time, and come out of the slime!\n\nAnd then maybe you can kill her and stop the slime. Yay!", sourceObjective = "Use Kitty's Eartag to get Winna Hazzard's attention, and then slay her.", progress = "Did it work?", completion = "Hooray! The forest will be safer now!\n\nYou're such a hero, {name}! With everything you've done for me and Mr. Tauren and the trees and animals and flowers, you deserve a reward!\n\nYay!", sourceObjectiveStatus = "unverified-source-field" }
quests[28214] = { id = 28214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup at Bloodvenom Post", description = "Blurgh...\n\nCould you... ugh... could you please... URGH!\n\nExcuse me, I'm still a little... ugh, my stomach. If you're going to Bloodvenom Post to the west, could you please HUUURGH...\n\nJust... just put what's left of my friends out of their misery. Go RIGHT NOW. For your own good. Uuuuurghh...", sourceObjective = "Slay 6 Bloodvenom Slimeslaves.", completion = "Thank you, {class}. I'm feeling much better now, and can appreciate the news that those abominations are gone.\n\nYou still might not want to stand too close, just in case...", sourceObjectiveStatus = "unverified-source-field" }
quests[28215] = { id = 28215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potential Energy", description = "As you well know, the amount of energy stored in a conventional spring is equal to one half the spring's elasticity times the displacement squared. Unless you're using an elementium spring. Then the numbers get obscene! Mathematically grotesque!\n\nI need some elementium loops for my secret weapon, and it just so happens that Twilight's Hammer cultists use coils like that to bind earth elementals.\n\nFind them on the Obsidian Stoneslaves east of here, in the terrible region known as the Black Breach.", sourceObjective = "Gather up 10 Twisted Elementium Coils.", progress = "If you start pulling heaps of elementium coils out of your backpack right now, you're going to make me one happy gnome!", completion = "Terrific! These coils will decompress with the force of a thousand suns!\n\nThat's just a rough approximation of course, don't hold me accountable for those numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28216] = { id = 28216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmalord Falthazar", description = "I just heard the terrible news from the west - we've lost Humboldt's Stead. Wiped off the face of the planet in a wall of fire!\n\nThe Twilight's Hammer is to blame, and the survivors say it were the work of one Magmalord Falthazar. He's an ascendant - that's what they call the highest echelon of Twilight's Hammer cultists who become one with the elements. He's a creature of pure fire.\n\nAnd he'll soon be a creature of pure dead! Go kill Falthazar at the Humboldt Conflagration and bring me his head!", sourceObjective = "Collect Magmalord Falthazar's Head.", progress = "All these years ol' Humboldt thought his worst problems were from the Glopgut ogres up on the ridge. Then the Twilight's Hammer came.\n\nIn an instant, they set the whole valley ablaze like it were a birthday cake. Heartless.", completion = "Aye, that's him. Can you believe this thing was human once?\n\nThat's the Twilight's Hammer for you. What they don't destroy, they corrupt.\n\nThank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28217] = { id = 28217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Demon Hunter", description = "Since reclaiming Jadefire Run from the satyr, the Emerald Circle has sent many druids to begin the long task of cleansing the ruins. Last night, several of them were murdered... by a night elf.\n\nThe witnesses say it was a demon hunter, a crazed disciple of Illidan. A rare sight. No doubt he's gone mad with power just like his master.\n\nI'll pay top bounty for proof of this murderer's death. He's been spotted just off the road to the north, in a valley beneath Jadefire Run.", sourceObjective = "Slay Feronas Sindweller.", progress = "So they sent another?", completion = "How noble of you... to blindly kill without question, to come for my head on the barest word of another.\n\nSheathe your fury and hear my tale first. You'll see what noble ignorance has done to these lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[28218] = { id = 28218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Destiny of Flame and Sorrow", description = "My kind has always been hated for what we do... despised outcasts, accused of corruption beyond redemption.\n\nYet if it was not for a demon hunter, these very woods would be the greatest stronghold of the Burning Legion on Azeroth. I speak of my master, Illidan Stormrage, the \"Betrayer\".\n\nSee for yourself. See what occured here when Illidan was first freed, and the demonic forces of the dreadlord Tichondrius ruled this forest completely unopposed...", sourceObjective = "Relive Illidan's battle with Arthas.", completion = "And so my master set out to find the skull... risking his own life against an army of demons to find the source of corruption in Felwood. Imagine if he had not! Imagine what these woods would look like if the Skull of Gul'dan had continued its work, undisturbed...", sourceObjectiveStatus = "unverified-source-field" }
quests[28219] = { id = 28219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzers for Baby", description = "<The tiny seedling opens its leaves wide, like a baby bird waiting to be fed. It speaks in a very faint voice:>\n\nHungry... want... bugs...<You can hear the buzzing of wasps to the south. Could they be what the little thing wants to feed on?>", sourceObjective = "Kill 10 Ironwood Buzzers to feed the Seedling Protector.", completion = "<The seedling pats its stalk with a rooty arm, as if full. It looks to have grown a bit, too!>", sourceObjectiveStatus = "unverified-source-field" }
quests[28220] = { id = 28220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Soil", description = "<The tiny sproutling shuffles around, motioning you towards the south. You can barely hear a faint voice.>\n\nSoil...\n\n<It looks like it wants fresh soil. Maybe you should guide it to some of the richer-looking patches.>", sourceObjective = "Bring the Seedling Protector to 7 patches of Rich Soil.", completion = "<The seedling coils its roots in what looks like a happy manner.>\n\nGrow... big...", sourceObjectiveStatus = "unverified-source-field" }
quests[28221] = { id = 28221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Roots Were Made For Stompin'", description = "There's so many other spirits still trapped in rotting bodies here...\n\nDo you see? The irontree stompers, in the north. They're sick with demon-stuff and icky with mold. Poor spirits inside them can't get out.\n\nYou can help! Chop them down, and the spirits can get out. I'll put the spirits in me and we can all be happy together when I grow up. Will you help? Please?", sourceObjective = "Slay 10 Irontree Stompers.", completion = "So happy! Can you hear us? We're so many friends now.\n\nBigger and bigger, with room for each friend...", sourceObjectiveStatus = "unverified-source-field" }
quests[28222] = { id = 28222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singin' in the Sun", description = "We're growing so much bigger... It's time to shine! Time to spread our leaves to the sun!\n\nTake me to the sun! The sun is far away, but its light comes to us. Its light makes us big and strong again. The light comes down the big branches to the little ones like ours.\n\nOver there! The sun comes to us in the north! Take us with you, take us to dance!", sourceObjective = "Guide the Sapling Protector to 5 shafts of sunlight in Irontree Woods.", progress = "More sun!", completion = "So warm and fresh and full of life. We love the sun, it makes us stronger.\n\nSoon now, very soon is the time of growing...", sourceObjectiveStatus = "unverified-source-field" }
quests[28223] = { id = 28223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden", description = "We have almost finished clearing out the revolting prisoners in The Hole, but one last problem remains.  The warden.\n\nWarden Silva is their master and they will do anything for him.  If we take him out, we take them all out.  Finish him off and bring me back his keys.  We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", sourceObjective = "You must kill Warden Silva in The Hole and return with his keys. The Hole is just southwest of Baradin Hold.", progress = "Is the warden dead yet?", completion = "Ahh, the wardens key's.  Another job well done, {name}.  These will come in very handy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28224] = { id = 28224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Protector", description = "Ahhh... thank you, little {race}. I and others have tried so many times to grow in this forest, without success.\n\nThe Withered Protector that lurks in the north is the only ancient to have grown to maturity since the ruining of the forest, but his body is sick and his mind is mad. Just as we gathered the spirits of the treants, I would save those that dwell in him rather than leave them behind.\n\nDefeat him, and let his spirits join me before I set my roots.", sourceObjective = "Defeat the Withered Protector.", progress = "All that is cut will regrow in time; the spirits endure.", completion = "Yes... it is time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28225] = { id = 28225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Yer Allegiance", description = "Yer welcome to stay in Chiselgrip for a time, but I need to know that yer a friend.  So I've got a task for ye.\n\nWe of the Thorium Brotherhood're not the only dark irons here in the steppes.  Far from it.  We're pretty badly outnumbered by the dark irons of Blackrock Mountain.  We've got a safe enough foothold here in Chiselgrip, but even so, they still pester us from as close as the Ruins of Thaurissan, to the north.\n\nProve yerself, {race}.  Kill 'em for me.", sourceObjective = "Kill 10 Dark Iron dwarves in the Ruins of Thaurissan.", completion = "Now that's what I like to see!  Yer alright, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28226] = { id = 28226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrapped Golems", description = "We keep golems here, as guards.  The dwarves to our north also keep golems, but I'm not sure why.\n\nMainly just for killin', I suppose.\n\nWe could use some spare parts for our own golems, so here's what yer gonna do: kill theirs, then look for any parts that might've fallen on the ground.  Salvage what ye can.  Ye probably won't be able to salvage everything, so choose carefully.", sourceObjective = "Kill War Reavers in the Ruins of Thaurissan, then loot 3 Obsidian Pistons, 3 Flux Exhaust Sieves, 3 Thorium Gearshafts, and 1 Stone Power Core from the War Reaver Parts that they drop.", progress = "We build these golems ourselves, ye know.  A little mechanical work, a little elemental work... the results aren't half bad, if ye ask me.", completion = "This is exactly what we needed.  I'll get the boys workin' on the next batch of golems right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[28227] = { id = 28227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golem Training", description = "Yer provin' to be a pretty big help around here, {race}.  I was thinkin ye could help with just one more thing.\n\nOur guards are strong, but they're not as strong as you are.  I was thinkin', maybe if ye wouldn't mind, ye might help some of 'em with their training?  Just go up and talk to one and fight 'em a few times.  Hopefully they'll learn from yer moves and get better.", sourceObjective = "Help 4 Chiseled Golems with their combat training.", completion = "Yer a lifesaver, {name}.  With golems like these, we won't have to worry about Dark Irons, Blackrock orcs... maybe even dragons!\n\nIf ye ever need anything from the Thorium Brotherhood, don't hesitate to ask.  That goes for yer friends, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[28228] = { id = 28228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejoining the Forest", description = "It is time to say goodbye now. You have raised me from a seedling, brief though it was, but now I must rejoin the forest.\n\nTake me back to the hill you found me on. There I will set my roots, and grow in the shadow of the ancients that came before me.You will be able to choose one of these rewards:", sourceObjective = "Bring the Flourishing Protector back to the hill in the center of Irontree Woods.", sourceObjectiveStatus = "unverified-source-field" }
quests[28229] = { id = 28229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature and Nurture", description = "The ancient protectors of Irontree Woods to the north have been dead for years, their bodies a grim symbol of the damage to these lands.\n\nEvery season, we take the water from this moonwell, and pour it on the ground before them, hoping it will nurture new life. If you'd like, you can deliver the water yourself.\n\nIt is an excellent opportunity for reflection. Take this vial and fill it at the moonwell, and pour it on the very top of the small hill between the three ancients.", sourceObjective = "Fill the vial at the moonwell in Whisperwind Grove and pour it on the ground between the dead ancient protectors in Irontree Woods.", sourceObjectiveStatus = "unverified-source-field" }
quests[28230] = { id = 28230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protocol", description = "Before the warden receives his comeuppance we must deal with the outbreak. We cannot risk this contagion being released into the world.\n\nWithin the laborers' quarters, directly north of here, is a monstrosity Stillwater pieced together out of three farmers. This beast must be destroyed if we are to secure the Sludge Fields! Protocol demands it!", sourceObjective = "Kill the Ray-Getz-Kalaba Monstrosity.", completion = "Once we deal with the rest of the undead we will confront Stillwater!", sourceObjectiveStatus = "unverified-source-field" }
quests[28231] = { id = 28231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do it for Twinkles", description = "Warden Stillwater sent me out into the field to investigate the outbreak. When I arrived, Twinkles and I were charged by the lumbering monstrosity known as Verringtan. I was knocked off of Twinkles and immediately ran for my life. Twinkles, though, stayed behind and fought the beast off. Alas, she was defeated and then summarily planted in the soil as if she were some type of glorious star pony seedling.\n\nShe gave her life to defend me. Vengeance must be mine! If for nothing else, do it for Twinkles!", sourceObjective = "Kill the Blacksmith Verringtan.", completion = "She may now ascend to the great horsey heaven in the stars. We will never forget you, Twinkles. NEVER!", sourceObjectiveStatus = "unverified-source-field" }
quests[28232] = { id = 28232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food From Below", description = "Supplies are running low here in camp, {name}.  We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use.  We need you to gather as many of those as you can and bring them back to camp.\n\nOne more thing, the entire cellblock is overrun with prisoners so be careful.", sourceObjective = "You have been asked to recover 12 Cellblock Rations from The Hole, just southwest of Baradin Hold.", progress = "Were you able to recover the rations?  Reports mentioned that they could be found all over the place down there.", completion = "These rations will really help the troops out {name}.  Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28233] = { id = 28233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Brother", description = "Me brother Bahrum has gone missing!\n\nHe was one of the first scouts in the area.  All the others have returned safely, but there be no sign of him.  Da says he's just dawdlin' somewhere, but he's me only brother, and I promised me mum that I would keep him safe.  Will you please find him?", sourceObjective = "Find Bahrum Forgehammer.", completion = "Don't be looking!  I'm not wearin' me pants!", sourceObjectiveStatus = "unverified-source-field" }
quests[28234] = { id = 28234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took Me Pants!", description = "Why I be standing in the grain crate?  Long story short, there were hornets and some Dragonmaw that showed up at a bad time.  I got away safely, but the bastards took off with me legguards!\n\nMy sister made those for me from scratch, even engraved my name on...  I would die of shame if she found out I lost 'em.\n\nPlease find 'em for me - I saw the pant thief going into that fortress over there.  I'm going to stay here for *ahem* cover.\n\nAnd don't be asking what a Wildhammer wears under his kilt!", sourceObjective = "Find Bahrum's legguards.", progress = "Have you found 'em yet?  This grain is pretty itchy.", completion = "Thank you!  Now turn around so I can put'em on.", sourceObjectiveStatus = "unverified-source-field" }
quests[28235] = { id = 28235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnside Must Fall", description = "Magistrate Burnside was once the mayor of this region. In life he was a formidable adversary in the battle over Hillsbrad. In undeath he will surely test us.\n\nBurnside channels great arcane magic in the northwest section of the Sludge Fields. Lead us there and together we shall put an end to his rule, once and for all.", sourceObjective = "Kill Magistrate Burnside.", progress = "Do not waste my time, {name}.", completion = "Now to bring Warden Stillwater to justice!", sourceObjectiveStatus = "unverified-source-field" }
quests[28237] = { id = 28237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blight Upon the Land", description = "With the undead outbreak contained, the time has come for Stillwater and his followers to answer for their crimes. Though we averted a tragedy the likes of which has not been seen since the Scourge invaded, we must ensure that such a thing can never happen again. They will all face true death!\n\nCome, {name}! I will have Stillwater's head!", sourceObjective = "Take the Head of Warden Stillwater.", progress = "Do not waste my time, {name}.", completion = "I will deliver this head to the Banshee Queen personally. Of course I will make mention of your part in all of this, {name}.\n\nAs for your reward - take from Stillwater's cache whatever you desire. You earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28238] = { id = 28238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Shores", description = "The time has come, {class}. With Stormwind secure, we will take this fight to the enemy. To the Highlands!\n\nThe bulk of our navy has already shipped out, thanks to your work earlier. But Fargo Flintlocke has prepared a seaplane that can make the journey in double-time.\n\nSpeak with Flintlocke down at the harbor and tell him that you are to accompany him to the Highlands. He will be by the water's edge. Safe journeys, {name}.", sourceObjective = "Speak with Fargo Flintlocke at Stormwind Harbor.", completion = "A ride to the Highlands, then? I've just the thing!\n\nI'll make room for yeh in me seaplane. I'll have to ditch the cat-food I was packing, yeh know, in case we crash in the mountains and ain't rescued fer weeks.\n\nOn second thought, jes' keep the cat food on yer lap, aye.", sourceObjectiveStatus = "unverified-source-field" }
quests[28239] = { id = 28239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Black Tooth Hovel", description = "This isn't really the most... convincing disguise I've seen, but it'll work.  Undercover work is all about swagger, anyhow.  Just act like you're supposed to be there, and you'll be fine.\n\nYour contact inside Black Tooth Hovel will be an orc by the name of Quartermaster Kaoshin.  He does NOT know you're a spy, so try and stay cool.\n\nDo whatever Kaoshin asks you.  Colonel Troteman will be in touch via gnomecorder to give you any special instructions.\n\nGood luck out there, soldier.", sourceObjective = "Speak with Quartermaster Kaoshin at the Black Tooth Hovel in Burning Steppes.\n\nProvided item:", completion = "Where have you been, grunt?  You're late!  Give me one reason why I shouldn't kill you on the spot!", sourceObjectiveStatus = "unverified-source-field" }
quests[28240] = { id = 28240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapped Out", description = "Listen, {name}.\n\nYou know I live to entertain you, and that I strive to keep you pleasantly occupied and whatnot.\n\nBut it just so happens that I've completely run out of ideas.\n\nThat was it!\n\nUsusally as I'm questing with you I can think of a few things to have you do next, which buys me time to cook up some grand objective, but no more.\n\nI'm tapped out. Completely uninspired. Couldn't muster up another idea to save my life.\n\nOh, wait!I know what we can do!\n\nTalk to me in a week or two...", sourceObjective = "Harrison Jones wants you to talk to him again in a week or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[28241] = { id = 28241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through these funny magical balls: \"The Eyes of Twilight.\"\n\nIf I could get me hands on one of those, I bet we could use it to look in on Cho'gall and see what his creeps are up to. Get me one!\n\nSearch the Black Breach, east of here and just north of the river. Find me an Eye of Twilight, and do whatever you gotta do to bring it back here.", sourceObjective = "Locate an Eye of Twilight within the Black Breach.", completion = "<The Eye sits before you, humming ominously with dark energies.>\n\n<Without warning, the orb rotates, as if to look at you. You sense a malevolent presence, as though the orb is alive.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28242] = { id = 28242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", sourceObjective = "Slay 10 Shaman of the Black.", progress = "I have been watching you, {race}.", completion = "<The Eye glimmers darkly, colors swirling about its dusky surface.>\n\nAh, the succulent thrill of life extinguished. Do you feel it, {class}? Do you relish it as I do?\n\nNo, I see not. You fight to protect the lives of others. Pity.", sourceObjectiveStatus = "unverified-source-field" }
quests[28243] = { id = 28243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to the \"Low Shaman\" of Thundermar.\n\nOh yes, I already know where you're taking me. Blundy's meager, ale-soaked abilities are trivial. But you - you fascinate me, {race}. With my sight and your abilities, imagine the havoc we could unleash into this pathetic world together...", sourceObjective = "Take the Eye of Twilight to Low Shaman Blundy at Thundermar in Twilight Highlands.", progress = "You again? Wot? You bring me somethun'?", completion = "You found one? A gen-u-ine Eye of Twilight? Lemme see.\n\nOh Gods. It's lookin' at me. It's lookin' right back!\n\nI need a drink. Can you face that thing toward the wall or somethin'?", sourceObjectiveStatus = "unverified-source-field" }
quests[28244] = { id = 28244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Spy", description = "I'll be honest, {name}. That thing gives me the willy-willies. But seein' as you went to all the trouble of bringin' it here, I s'pose we ought to put it to use.\n\nYou first.\n\nPeer into the eye and ask it to show you inside Cho'gall's Bastion of Twilight. We'll find out what that fat two-headed bugger is up to, and use it against him.", sourceObjective = "Peer into the Eye of Twilight for Low Shaman Blundy.", progress = "Whad'ya see, {class}?", completion = "What did you see, {name}? Cho'gall? Wait - he saw YOU!?\n\nOh aye, that wee sneaky eye! It looks both ways. That cheeky looker! Where's me hammer!?", sourceObjectiveStatus = "unverified-source-field" }
quests[28245] = { id = 28245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunt Work", description = "Bah!  You're lucky I'm short-handed today.  Otherwise I'd make you my personal whipping <boy/girl> for the week.\n\nThe officers and high-ranking soldiers need their boots polished.  They've left them out in front of their huts.\n\nI want to see my reflection in those boots, grunt!  Get to work!", sourceObjective = "Vigorously polish 7 pairs of Blackrock Boots.", progress = "Oh, you're asking for it now, grunt.", completion = "Hmph.  Good work, grunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28246] = { id = 28246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Cuts", description = "<Static> {name}... {name}, can you hear me?  It's Troteman.\n\nListen, we've just received the final bit of intel for your next mission.  There are three marks that we'd like you to take down.  The first is Voodooist Timan, whom you'll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.\n\nYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.", sourceObjective = "Use the Razor-Sharp Scorpid Barb on Voodooist Timan atop the Pillar of Ash, Worgmistress Othana in the worg pens, and Gorlop when he is near the lava pools.", completion = "Not only did you pull off the executions, you made them all look like accidents!\n\nYou were the right {race} for this undercover work.  Good job, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[28247] = { id = 28247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last of Her Kind", description = "Obsidia is one of the last mature dragons that can continue the black dragonflight bloodline. She must be killed.\n\nIf you succeed in killing her, you should inform Lirastrasza immediately of your victory. She's been fighting a long time to see this done.\n\nThank you for being our fang in these battles. You've proven a powerful ally.", sourceObjective = "Kill Obsidia.", completion = "You killed Obsidia within her own lair? Impressive, {race}. I'm sorry that I could not be there.\n\nYou're true to your word, and you most certainly have the bite to back your bellow. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28248] = { id = 28248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victors' Point", description = "You've more than proved your intent and your abilities. With Grim Batol cut off and the black dragons routed, the Twilight's Hammer are cornered in their Citadel.\n\nGo to your leaders. You should find them northwest, at Victors' Point. Let them know that when the attack on the Twilight Citadel begins, the red flight shall fill the skies above. You may not be able to atone for all of the sins your allies have committed, but in this one battle, we shall be by your side.\n\nThe Twilight's Hammer will fall.", sourceObjective = "Speak to Kurdran Wildhammer at Victor's Point.", completion = "You've done well, {name}. We're in the process of preparing the attack now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28249] = { id = 28249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushblow", description = "You've more than proved your intent and your abilities. With Grim Batol cut off and the black dragons routed, the Twilight's Hammer are cornered in their Citadel.\n\nGo to your leaders. You should find them west, at Crushblow. Let them know that when the attack on the Twilight Citadel begins, the red flight shall fill the skies above. You may not be able to atone for all of the sins your allies have committed, but in this one battle, we shall be by your side.\n\nThe Twilight's Hammer will fall.", sourceObjective = "Speak to Warlord Zaela at Crushblow.", completion = "You've done well, {name}. We're in the process of preparing the attack now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28250] = { id = 28250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Little Pluckers", description = "I don't have the most glamorous job in the world.\n\nI do not concern myself with matters of war or the deep mysteries of the halls of Uldum or what have you.\n\nI am in charge of these grounds... and these grounds grow dates.\n\nNow, these little date-plucking mongrels have gotten gutsy enough to stand on each other's shoulders to try and steal my precious fruit.\n\nI will not stand for this.\n\nTake this mallet, crafted by the titans, blessed by the sun-kings and who-knows-what-else and smash the runts!", sourceObjective = "Smash 30 Sand Pygmies with the Tahret Dynasty Mallet.", progress = "Did you do it, {name}?", completion = "You showed those thieving little scoundrels!  Great job.", sourceObjectiveStatus = "unverified-source-field" }
quests[28251] = { id = 28251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Southshore", description = "Before my capture and imprisonment, I was stationed at Southshore. My primary job at the ruins was to take slime samples and make sure that the blight that we released was safely dissipating. Simple and easy if not for the worgen that would continuously harass us.\n\nI need you to head to Southshore and find my apprentice, Serge Hinott. Make sure that he's ok and inform him that I will return once my work here has concluded.\n\nYou'll find the Ruins of Southshore to the southeast, near the coast.", sourceObjective = "Speak to Serge Hinott at the Ruins of Southshore in Hillsbrad Foothills.", completion = "The worgen situation hasn't gotten any better and Helcular is really creeping me out.", sourceObjectiveStatus = "unverified-source-field" }
quests[28252] = { id = 28252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kodocaller's Horn", description = "Alright, I've got some actual, legitimate, important work for you.  We've got to call the kodos in from the grazing lands to the south.  General Thorg'izog says we'll be moving out into Redridge soon, and I won't be caught with my kodos down.\n\nUse this horn near a kodo.  It will return to the camp when it hears the call.\n\nYou'll want to watch out.  Sometimes the kodos get a little feisty, so you need to knock them around a bit before they listen to you.", sourceObjective = "Use the Horn of the Callers to call 7 Blackrock War Kodos back to camp. If a kodo turns hostile, fight it until it submits.", sourceObjectiveStatus = "unverified-source-field" }
quests[28253] = { id = 28253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Horn For Ourselves", description = "{name}, it's Troteman.  I want you to hold onto that horn.  I'm sure we can improvise and find a way to work it into the plan.\n\nI'm more than a little concerned about what Kaoshin said about attacking Redridge.  We knew another attack was imminent, but our timetables were off by several days.\n\nReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You're not done with your undercover work yet.", sourceObjective = "Bring the Horn of the Callers back to Colonel Troteman at Chiselgrip in Burning Steppes.", progress = "Welcome back, soldier.", completion = "I didn't count on obtaining an item like this.  I will change our plans accordingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[28254] = { id = 28254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Needle in a Hellhole", description = "You and I can't take on an army, {name}.  They'll overwhelm us.  That's why we've got to stick to Troteman's plan.\n\nThe next part of the plan is going to require a bit of subtlety... something that I'm not terribly good at.  That's where you come in.\n\nSpeak with Thelaron Direneedle, the tailor here in town.  I've already given him the hides and mud that we've collected.  He's going to need to size you.\n\nThat's right, {name}: you're going undercover.", sourceObjective = "Speak with Thelaron Direneedle at Chiselgrip in Burning Steppes.", completion = "You need a disguise?  Well, you came to the right place, honey.\n\nLet me take a look... mm-hmm.  I know exactly what we'll do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28255] = { id = 28255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vhat's Next?", description = "Vhich vay vill zhings turn out? Hmm?\n\nVill I turn on my dark master, whoever zhat might be?\n\nVill I learn to become a more sensitif and compassionate leader? Vill I go so far as to drop my adorable dialect?\n\nOr vill I embrace my aspirations and press forvard at all costs, never satisfied until all of Azerozh is mine?\n\nAnd vhat zhen, hmm?\n\nMaybe it vill all come togezher next veek...\n\n...or maybe zhe veek after zhat...", sourceObjective = "Commander Schnottz just wants a hug...", sourceObjectiveStatus = "unverified-source-field" }
quests[28256] = { id = 28256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skull of Gul'dan", description = "Illidan set out to find the Skull of Gul'dan. He fought through armies of demons to reach it, slaying them with the power that made him a hated outcast.\n\nSee him in battle, {class}. Witness the one that fought the fiercest against the corruptors of Felwood, and struck at its source.", sourceObjective = "Relive Illidan's battle for the Skull of Gul'dan.", completion = "Now you are beginning to see...", sourceObjectiveStatus = "unverified-source-field" }
quests[28257] = { id = 28257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Tichondrius", description = "Yes, Illidan took the power of the Skull of Gul'dan for himself.\n\nBut did he flee with it into the night? Did he use it for his own glory? No... his very first action was to use his new power to assault the dreadlord Tichondrius!\n\nWitness his triumph, {class}. Witness how Illidan reclaimed Felwood from the demons... and the thanks he was given.", sourceObjective = "Relive Illidan's battle with Tichondrius.", completion = "Do you see now? For doing what was needed to drive the demons from these lands, my master was banished.\n\nNow these druids pick up the pieces, patting themselves on the back for scrubbing the remaining vestiges of the legion's forces.\n\nBut that is not why I killed them.", sourceObjectiveStatus = "unverified-source-field" }
quests[28258] = { id = 28258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Ander Germaine", description = "Ander Germaine sent a message for you. He wants you to join him at his headquarters in the Command Center in Stormwind's Old Town as quickly as you can. It sounded important, {name}.", sourceObjective = "Speak with Ander Germaine at the Command Center south of Stormwind's Old Town.", completion = "It's good to see you again, {name}. I wish I could say that I had happy news.", sourceObjectiveStatus = "unverified-source-field" }
quests[28259] = { id = 28259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Demisette Cloyce", description = "I just received a scroll from Demisette Cloyce in Stormwind. She wants you to pay a visit to the Slaughtered Lamb in Stormwind. She doesn't mention specifics, but I got the impression that it was a matter of some importance.", sourceObjective = "Speak with Demisette Cloyce in the basement of the Slaughtered Lamb in Stormwind's Mage District.", completion = "I see you received my message. An opportunity has presented itself, {name}, one which will allow us to demonstrate just how important we are to the success of Stormwind and the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[28260] = { id = 28260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Wulf Hansreim", description = "Wulf Hansreim sends word from Stormwind -- he wants to meet with you right away. He'll be in the Command Center just to the south of Stormwind's Old Town.", sourceObjective = "Speak with Wulf Hansreim in the Command Center to the south of Stormwind's Old Town.", completion = "I'll be brief, {name}. Our enemies are gathering and Stormwind needs our help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28261] = { id = 28261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceivers In Our Midst", description = "Now that you've had a lesson in keeping an open mind, perhaps you'd like to learn WHY I killed those druids.\n\nThe answer is simple: They are not druids at all.\n\nDemons still roam the ruins, now hiding in plain sight in the guise of friendly caretakers. See for yourself...this blindfold is soaked in demon blood. Take it north up the hills to Jadefire Run and place it on your eyes. It will show even the most oblivious fool the true nature of any demon.", sourceObjective = "Slay 12 Jadefire Shifters in Jadefire Run.", progress = "Don't tell me you would leave the demons to walk among us unopposed?", completion = "Enough! Your enthusiasm is impressive, but foolish. Gazing through the veil for too long without practice will break your mind.\n\nThe rest will be mine, {name}. For now, I summon you back to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[28262] = { id = 28262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Lord Tony Romano", description = "Lord Tony Romano, one of the senior rogue trainers in Stormwind's SI:7, has sent word that he wants to speak with you. Head to Stormwind as soon as you can and look for him in the SI:7 building just south of Old Town.", sourceObjective = "Speak with Ander Germaine at the Command Center south of Stormwind's Old Town.", completion = "Welcome, {name}. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[28263] = { id = 28263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Maginor Dumas", description = "I just received a message from Maginor Dumas, the senior mage trainer in Stormwind. He's asking you to join him in the Wizard's Sanctum in Stormwind as soon as you can travel there.", sourceObjective = "Speak with Maginor Dumas at the Wizard Sanctum in Stormwind's Mage Quarter.", completion = "It's good to see you again, {name}. Stormwind has need of your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[28264] = { id = 28264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navarax's Gambit", description = "I have been preying on these demonic impostors for some time now, and I have finally gleaned the location of their leader. It is none other than Arch Druid Navarax, the leader of the Emerald Circle.\n\nThe demon shields himself with innocents. If I entered Whisperwind Grove to hunt him, I would be set upon by ignorant protectors... but you! You can catch him unaware.\n\nReturn to Whisperwind Grove. Climb the druid tower and you'll find Navarax at the top, in his room amidst the boughs.", sourceObjective = "Slay the demon impersonating Arch Druid Navarax.", progress = "Have you anything to report?", completion = "I find it hard to believe everything you say, but the body of that demon is grim proof.\n\nI will order an investigation into the druids at Jadefire Run right away, and make sure my higher-ups know the demon hunter may be content to remain in exile.", sourceObjectiveStatus = "unverified-source-field" }
quests[28265] = { id = 28265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin turned out to be more helpful than I expected, but we're done with him.  It's time you spoke with the General.  I think you're ready.\n\nGeneral Thorg'izog is one of the \"big three\" that run the ground forces here in Burning Steppes.  He does so from the Blackrock Stronghold to the northwest.  Put on your disguise and go speak with him.  See if you can earn his trust.  Troteman will be in touch, should we need anything further.", sourceObjective = "Speak with General Thorg'izog.", completion = "More outsiders?  What do you want?", sourceObjectiveStatus = "unverified-source-field" }
quests[28266] = { id = 28266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial by Magma", description = "I suppose I'll make the most of this situation.  These goblin mercenaries brought this enormous fire elemental to my stronghold as a \"thank you\" for hiring them.  What am I going to do with an elemental here in the steppes?  That's like bringing sand to the beach.\n\nIf you're looking for work, then prove yourself.  Talk to this goblin here, and challenge his elemental to a fight.  The victor earns my respect, and my time.", sourceObjective = "Speak with Wyrtle Spreelthonket and ask him to release Magma Lord Kolob. Then defeat Magma Lord Kolob in battle.", progress = "What's the matter, are you scared?", completion = "I had a feeling you'd be the one returning to me.  I like your style, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[28267] = { id = 28267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firing Squad", description = "Come out back vizh me, {race}.\n\nZhere is somezhink I vould like you to see.", sourceObjective = "Speak to Commander Schnottz.", completion = "So, this Schnottz character is working with Deathwing!?\n\nThis is even more distressing than you think...", sourceObjectiveStatus = "unverified-source-field" }
quests[28268] = { id = 28268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Lord Grayson Shadowbreaker", description = "Lord Grayson Shadowbreaker from the Cathedral of the Light in Stormwind has sent a message for you. He wants to speak with you the next time you're in the city. You should be able to find him in the Cathedral District.", sourceObjective = "Speak with Lord Grayson Shadowbreaker at the Cathedral of Light in Stormwind's Cathedral District.", completion = "I wish had good news to share with you, {name}, but the truth is that I have asked you here because we have need of your talents.", sourceObjectiveStatus = "unverified-source-field" }
quests[28269] = { id = 28269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me In Vir'sar", description = "So, listen to this, {name}.\n\nI knew that these obelisks were linked to the Coffer of Promise, but there's more to it.\n\nThere appears to be something very important about the coffer - something pertaining to a place the Makers called the Halls of Origination.\n\nNow that we know this Schnottz fellow and his crew are in league with Deathwing, it's all the more urgent that we get to it first.\n\nI'll wait for you north of here, at the Oasis of Vir'sar\n\nHurry! They have a head start on us!", sourceObjective = "Speak to Harrison Jones at the Oasis of Vir'sar.", completion = "Ahh, glad you could make it.\n\nI could use a hand here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28270] = { id = 28270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding Shotgun!", description = "Alright, {name}, I'm very close to learning how to activate the final obelisk.\n\nOnly a few pieces of information are missing and with any luck, we should be able to find them at the site.\n\nThe supplies are all packed up. Let me know when you're ready to go.You will be able to choose one of these rewards:", sourceObjective = "Accompany Harrison to the Oasis of Vir'sar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28271] = { id = 28271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduced Productivity", description = "Alright, {name}, here's what I've learned.\n\nThere's a titan device deep in a place called the Halls of Origination. It's meant to be an emergency reset switch for all life on Azeroth. If activated, it will destroy every living thing in the world!\n\nNow, it's only meant to be used under certain extreme conditions, but if Deathwing is able to corrupt the titan watchers, he could use the contents of the coffer to trigger the device.\n\nGo to the Obelisk of the Moon, {name}. Slow them down!", sourceObjective = "Kill 15 Schnottz Excavators or Schnottz Overseers.", progress = "How'd it go out there, {name}?", completion = "Good job with Schnottz's men.\n\nSounds like you gave them something to think about.\n\nHopefully it bought us the time we need.", sourceObjectiveStatus = "unverified-source-field" }
quests[28272] = { id = 28272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Pieces", description = "There are just a few specific pieces of information that I'm missing.\n\nOnce those blanks are filled, we'll be ready to activate the final obelisk. Then, it'll be a race to discover the Coffer of Promise before Schnottz and his cronies can.\n\nThose fools are excavating this site as fast as they can. They're ruining more than they're looting!\n\nGo to the obelisk and rummage through their booty, {name}.\n\nSee if you can find our missing pieces.", sourceObjective = "Collect 7 Ancient Copper Scrolls.", progress = "Were you able to find anything interesting, {name}?", completion = "<Harrison quickly skims through the scrolls.>\n\nYes... yes... perfect!\n\nI'll need some time to make sense of these, but the information is there.\n\nGood work, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28273] = { id = 28273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of a Friend", description = "I need to unpack and look around the area a bit. In the meantime, I have an old friend I'd like you to meet.\n\nSullah and I go way back. He's a man who can be trusted, and that's pretty rare these days.\n\nWhy don't you go on over and introduce yourself.", sourceObjective = "Harrison wants you to speak to Sullah at Oasis of Vir'sar.", completion = "Welcome {class}!\n\nYou and I are going to be good friends! I can tell already.", sourceObjectiveStatus = "unverified-source-field" }
quests[28274] = { id = 28274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Tents", description = "Look at you, my friend. This grand adventure of yours has you in knots!\n\nYou need to relax and unwind. You're too tense, and that's just going to tire you out.\n\nTrust me, I know about relaxing!\n\nSpeaking of tents, I see Jonesy brought me the ones I asked for.\n\nCome, friend. Ride with me!", sourceObjective = "Accompany Sullah to Sullah's Sideshow.", completion = "Here we are, {name}!\n\nGreat things will happen here... magical things!", sourceObjectiveStatus = "unverified-source-field" }
quests[28275] = { id = 28275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead over there and see what you can do.  Report back to me on your progress.", sourceObjective = "Destroy 10 Ghastly Supply Boats.", completion = "Great work on those supply ships, {name}!  We knew you would be good for somethin' around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28276] = { id = 28276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet's Secret", description = "Listen, {name}.  Before you give up on me, there's something I'd like to show you.\n\nYou see, I'm not much of a fighter.  I'm not very coordinated.\n\nI'm more of a tactical mind.\n\nMeet me at the southern end of the ridge and I'll show you.", sourceObjective = "Find Salhet at the Southern End of the Sunwatcher's Ridge in Uldum.", completion = "Aren't they beautiful?", sourceObjectiveStatus = "unverified-source-field" }
quests[28277] = { id = 28277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet the Tactician", description = "Ever since I was a cub, I've always wanted to be a general.\n\nI was eager to join the army.  But as you've seen, my combat skills are not all quite there.\n\nThis is not the first time I've been sent to kill hyenas.  As a matter of fact, I get sent here so often, that I've befriended these lions and trained them to do my bidding.\n\nThey are my soldiers and at my command they will slay legions of hyenas.  Watch!", sourceObjective = "Speak to Salhet and slay 30 Bloodsnarl Scavengers", progress = "Did you see, {name}?", completion = "Not bad, huh?  Maybe you can put a word in with the high commander.\n\nMaybe he'll put us in charge of our own squad!", sourceObjectiveStatus = "unverified-source-field" }
quests[28278] = { id = 28278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Law and I Am the Lash", description = "I've been looking for a good, strong soldier like you.  I need someone to keep my troops in line.\n\nOutside the stronghold, you will find orcs, ogres, and trolls preparing for the assault on Redridge.  My sergeants keep them in line, but I'd like you to assist them.\n\nTake this cudgel and discipline a few of my soldiers.  I don't care if they're misbehaving or standing perfectly in line, I want them beaten.  I want them focused, battle-hardened, and obedient.\n\nNow go.", sourceObjective = "Use the Blackrock Cudgel of Discipline on 20 troops in the Fields of Honor. If one of the troops discovers your disguise, cudgel him to death before he can unmask you.", completion = "I have a feeling we'll be hearing about you and your exploits for a long time, soldier.  I look forward to fighting by your side in Redridge.\n\nYou are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28279] = { id = 28279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abuse of Power", description = "{name}?  Troteman here.\n\nIt sounds like you have earned Thorg'izog's trust, and he's assigned you to discipline duty.  This is fortunate.\n\nWe need you to take out his sergeants.  You'll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You'll have to act fast, because if they realize you're not one of them, they can unmask you.  Strike quickly and ferociously, {name}.\n\nTroteman out.", sourceObjective = "Kill 5 Blackrock Sergeants using the Blackrock Cudgel of Discipline. Defeat them quickly, before they have a chance to unmask you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28280] = { id = 28280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear Them From the Sky!", description = "Egah! They're here, {name}. They're here!\n\nI had hoped to equip a whole army with my shoulder-mounted drake-droppers, but all I have is a single, extremely expensive and wholly untested prototype. Here, take it!\n\nShoot the Dragonmaw black drakes that are circling Thundermar, and drop them from the sky!", sourceObjective = "Use the Shoulder-Mounted Drake-Dropper to slay 8 Dragonmaw Black Drakes.", completion = "You did it, {name}! Alliance ingenuity to the rescue.\n\nOf course, I don't have anything to help you fight the dismounted riders now that they're on the ground. You're a {class}; improvise!", sourceObjectiveStatus = "unverified-source-field" }
quests[28281] = { id = 28281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand at Thundermar", description = "I'll hand it to you and your Alliance friends. You've really worked the Dragonmaw over!\n\nMany of their riders are dismounted but they're still coming at us, and my defenders will be overrun without help.\n\nKill Dragonmaw Skyclaws on foot and Thundermar will forever be in your debt!", sourceObjective = "Kill 8 Dragonmaw Skyclaws on foot.", progress = "We'd best finish fighting and put these fires out, or Thundermar will look like the rest of the wreckage...", completion = "You sure know your way around a battlefield, {class}. It looks like they're about to fall back.\n\nAll we need is one decisive blow...", sourceObjectiveStatus = "unverified-source-field" }
quests[28282] = { id = 28282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, The Drake-Tamer", description = "There's one Dragonmaw among this lot, the one they call \"Narkrall: The Drake-Tamer.\" I don't know where he gets his power over those beasts, but the black terror he rides is as nasty a brute as ever took the skies over the Highlands.\n\n{name}, Narkrall is the fiend who took my father's life and left Thundermar in my hands.\n\nI can't take him on alone, but I've seen what you're capable of, {class}. Maybe together we can end this.\n\nLet me know when you're ready, and we'll fight Narkrall together!", sourceObjective = "Slay Narkrall Rakeclaw. Speak with Colin Thundermar when you're ready.", progress = "Narkrall. With a heart as black as the beast he rides.", completion = "We did it, {name}! Narkrall Rakeclaw lies dead at my feet, and Thundermar has weathered a storm of drakes!\n\nThis wouldn't have been possible if it weren't for the help of the Alliance. I owe you a debt that I don't think can ever be repaid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28283] = { id = 28283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's that Rattle?", description = "Did you see that glowing rattle on the ground outside of Isha's hut?", sourceObjective = "Inspect the Rattle of Bones on Darkcloud Pinnacle in Thousand Needles.", completion = "Interesting....", sourceObjectiveStatus = "unverified-source-field" }
quests[28284] = { id = 28284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's that Rattle?", description = "Did you see that glowing rattle on the ground outside of Isha's hut?", sourceObjective = "Inspect the Rattle of Bones on Darkcloud Pinnacle in Thousand Needles.", completion = "Interesting....", sourceObjectiveStatus = "unverified-source-field" }
quests[28285] = { id = 28285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with High Priestess Laurena", description = "I just received a scroll from the Cathedral of Light, {name}. High Priestess Laurena sends word that she wishes to speak with you. You should meet with her as soon as you can.", sourceObjective = "Speak with High Priestess Laurena at the Cathedral of Light in Stormwind's Cathedral District.", completion = "The Light has answered my prayers. At last, you have arrived.", sourceObjectiveStatus = "unverified-source-field" }
quests[28286] = { id = 28286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Damage For One Day", description = "We do not have any further strategic need for Thorg'izog or the Blackrock ground troops.  We must continue to the next phase of the plan.\n\nWhen you are finished at the stronghold, return to us here in Chiselgrip.", sourceObjective = "Return to Colonel Troteman at Chiselgrip.", completion = "You alright?\n\nGood.  You did a fine job out there, {name}.  Now pack up your things.  We're moving out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28287] = { id = 28287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Farseer Umbrua", description = "Farseer Umbrua's messenger just reached me, {name}. She has an important matter she wishes to discuss with you and sends word that you should meet her at the Golden Keg in the Dwarven District of Stormwind as soon as you can make it there.", sourceObjective = "Speak with Farseer Umbrua at the Golden Keg in Stormwind's Dwarven District.", completion = "Welcome, {name}. We will need your skills in the continuing battle against Twilight's Hammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28288] = { id = 28288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open Their Eyes", description = "Before you go...\n\nI've taken advantage of my \"alone time\" with Impsy here to learn some interesting facts about imps. Specifically, he ended up telling me the one thing that all imps fear most. Something they're absolutely terrified of.\n\nI thought that sounded useful as well as interesting, so I've done some basic conjuring. This prism will project an image of... well, of what Impsy described.\n\nShadowlurk Ridge is still swarming with imps. Why don't you go test their reaction for me?", sourceObjective = "Use Delaris's Prism to terrify 20 Jadefire Imps.", completion = "I see... their eyes are open\n\n<Delaris smiles with bemusement.>\n\nMaybe I'll keep Impsy around after all. He's got a lot to teach me...", sourceObjectiveStatus = "unverified-source-field" }
quests[28289] = { id = 28289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglade Calls", description = "I have received word that our brothers in Moonglade have requested your help, {name}. You should travel there and speak with Loganaar in Nighthaven. He will tell you all you need to know.", sourceObjective = "Travel to Moonglade and speak with Loganaar in Nighthaven.", completion = "It's good to see you again, {name}. I wish I could say that I had happy news.", sourceObjectiveStatus = "unverified-source-field" }
quests[28290] = { id = 28290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Grezz Ragefist", description = "Grezz Ragefist sent an urgent message for you, {name}. He wants you to join him immediately in Orgrimmar's Valley of Heroes. He must have a mission of importance for you.", sourceObjective = "Speak with Grezz Ragefist in Orgrimmar's Valley of Honor.", completion = "The Horde has need of your skills, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28291] = { id = 28291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Camp", description = "What do you think, {name}?  Maybe the High Commander will give me a few men to command.\n\nMaybe we can marshal a regiment together.  What do you think?", sourceObjective = "Return to High Commander Kamses at the Ramkahen Legion post.", completion = "Salhet?  A tactician, you say?\n\nHah!  Very well, if you'll vouch for him, we might be able to arrange something.", sourceObjectiveStatus = "unverified-source-field" }
quests[28292] = { id = 28292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's No Pyramid!", description = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses.\n\nDeathwing was going to have the Twilight's Hammer turn it into a massive weapon!\n\n{name}, you have to take the portal to get this information to Harrison Jones in Stormwind. He'll know what to do.", sourceObjective = "Speak with Harrison Jones at Stormwind Keep in Stormwind City.", completion = "Uldum? What about it?", sourceObjectiveStatus = "unverified-source-field" }
quests[28293] = { id = 28293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's No Pyramid!", description = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses.\n\nDeathwing was going to have the Twilight's Hammer turn it into a massive weapon!\n\n{name}, you have to take the portal to get this information to Belloc Brightblade at Grommash Hold in Orgrimmar. He'll know what to do.", sourceObjective = "Speak with Belloc Brightblade at Grommash Hold in Orgrimmar.", completion = "Uldum? What about Uldum? Speak quickly!", sourceObjectiveStatus = "unverified-source-field" }
quests[28294] = { id = 28294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kirthaven Summit", description = "After the licking we just gave 'em, the Dragonmaw assaults on Thundermar ought to stop. Maybe the Wildhammer do have a place in your Alliance - we Thundermars certainly owe you a debt.\n\nUp in Kirthaven, our Grand Shaman Lachlan MacGraff has been trying to arrange a summit between the surviving Wildhammer family leaders. It's a tall order to get us all to work together, but I'm at least willing to give it a go.\n\nFly up to Kirthaven in the North and talk to Lachlan MacGraff. I'll meet you there!", sourceObjective = "Speak with Lachlan MacGraff at Kirthaven in Twilight Highlands.", completion = "Hello, {class}! Keegan Firebeard here has told me all about your heroics down south. Thank you for all of your efforts on behalf of the Wildhammer.\n\nI see Colin Thundermar is right behind you. The summit is ready to begin! Please stay and let's see how things unfold...", sourceObjectiveStatus = "unverified-source-field" }
quests[28295] = { id = 28295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meetup with the Caravan", description = "The pyramid inside of the Maker's Terrace in Uldum can be used as some kind of super weapon that will end all life on Azeroth.\n\n<Harrison thinks a moment.>\n\nYou need to continue the research you've begun. Head to the southern end of Kalimdor, to the desert of Tanaris. There's a caravan there that's about to leave for Uldum.\n\nPerhaps you can tag along.", sourceObjective = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", completion = "Harrison sent you, hmm?\n\nHow fortunate!", sourceObjectiveStatus = "unverified-source-field" }
quests[28296] = { id = 28296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meetup with the Caravan", description = "The pyramid inside of the Maker's Terrace in Uldum can be used as some kind of super weapon that will end all life on Azeroth.\n\n<Belloc thinks a moment.>\n\nYou must continue the good research that you've begun. Head south to the desert of Tanaris. There's a caravan there that's about to leave for Uldum.\n\nPerhaps you can tag along.", sourceObjective = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", completion = "Belloc sent you, hmm?\n\nHow fortunate!", sourceObjectiveStatus = "unverified-source-field" }
quests[28297] = { id = 28297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Ormak Grimshot", description = "I received a scroll for you from Ormak Grimshot in Orgrimmar. He wants you to make your way to the Valley of Honor and speak with him as soon as you can. It sounded urgent, {name}.", sourceObjective = "Speak with Ormak Grimshot in Orgrimmar's Valley of Honor.", completion = "The Horde has need of your skills, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28298] = { id = 28298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Gordul", description = "Gordul, leader of the rogues of the Shattered Hand in Orgrimmar, wishes to meet with you. Make your way to Orgrimmar quickly, {name} and seek him in the Cleft of Shadow. He must have an important mission for you.", sourceObjective = "Speak with Gordul in Orgrimmar's Cleft of Shadow.", completion = "The Shattered Hand needs your skills, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28299] = { id = 28299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Zevrost", description = "I have just received word from Zevrost, Orgrimmar's foremost warlock trainer. He wishes you to travel to Orgrimmar and speak with him in the cleft of shadow. It sounds like he has an important mission for you.", sourceObjective = "Speak with Zevrost in Orgrimmar's Cleft of Shadow.", completion = "The Horde will soon call upon your skills, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28300] = { id = 28300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Ureda", description = "I just received a scroll for you from Orgrimmar, {name}. It's from Ureda, one of the mage trainers there. She wants you to meet with her in Orgrimmar's Cleft of Shadow next time you're in the city.", sourceObjective = "Speak with Ureda in Orgrimmar's Cleft of Shadow.", completion = "The Horde needs your help in the battle against our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[28301] = { id = 28301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Kardris Dreamseeker", description = "I just received an urgent message addressed to you, {name}. It's from Kardris Dreamseeker, one of the shaman trainers in Orgrimmar. She wants you to travel to Orgrimmar's Valley of Wisdom and speak with her as soon as you can.", sourceObjective = "Speak with Kardris Dreamseeker in Orgrimmar's Valley of Wisdom.", completion = "These are dangerous times, {name}. The Horde is fortunate to have {race} like you in its ranks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28302] = { id = 28302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Sunwalker Atohmo", description = "You should make your way to Orgrimmar as soon as you can, {name}. Sunwalker Atohmo has sent word that he wishes to speak with you about a matter of importance to the Horde. Look for him the Valley of Wisdom.", sourceObjective = "Speak with Sunwalker Atohmo in Orgrimmar's Valley of Wisdom.", completion = "The Horde will soon have need of your skills, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28303] = { id = 28303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Master Pyreanor", description = "Master Pyreanor sent an urgent message for you, {name}. He asks you to join him at Grommash Hold in Orgrimmar's Valley of Strength the next time you're in the city. It sounds as though he must have an important assignment for you.", sourceObjective = "Speak with Master Pyreanor in Orgrimmar's Grommash Hold.", completion = "You are one of the most promising young paladins I have ever trained, {name}. It is for that reason that I wish to offer you a dangerous mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[28304] = { id = 28304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Dark Cleric Cecille", description = "Dark Cleric Cecille, a member of the Banshee Queen's delegation to Orgrimmar, has requested to meet with you next time you're in the city. You can find her inside Grommash Hold in Orgrimmar's Valley of Strength. It must be an important matter for her to send for you so directly, {name}.", sourceObjective = "Speak with Dark Cleric Cecille at Grommash Hold in Orgrimmar's Valley of Strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[28305] = { id = 28305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Bloodvenom Post", description = "While we dealt with Jaedenar, I sent a friend of mine north to Bloodvenom Post. We used to have infrequent visits from the tauren there, but they have stopped coming as of late.\n\nMy friend, Kelnir Leafsong, has yet to return. Would you travel north to check on her and the situation at Bloodvenom?\n\nShould you find her, do be aware... dryads like her tend to strike other races as a bit odd.", sourceObjective = "Speak with Kelnir Leafsong at Bloodvenom Post.", completion = "Oh, hi! Did Farlus send you? I'm so happy he remembered!\n\nBloodvenom Post is all overrun with awful slime thingies, and this poor tauren is the only one left! We've got to help him!", sourceObjectiveStatus = "unverified-source-field" }
quests[28306] = { id = 28306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whisperwind Grove", description = "You've been such a big help here!\n\nI'm gonna stay here a while and look after poor Mr. Tauren until he stops throwing up so much. Why don't you head north to Whisperwind Grove? It's really pretty there, and all the druids are so friendly!\n\nYou should tell Miss Puregrove I'm okay, she'll worry if I'm gone too long. She might ask you to help with her flowers, too! So fun!", sourceObjective = "Speak with Tender Puregrove at Whisperwind Grove.", completion = "Kelnir? Hahaha...\n\nSometimes I wonder if her chatter drove all the other dryads away. But I'm glad she is safe.\n\nWelcome to Whisperwind Grove, {class}. Hold peace in your heart, and you will find a home here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28307] = { id = 28307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Tyelis", description = "Tyelis, a member of the the Silvermoon delegation to Orgrimmar, has requested to meet with you next time you're in the city. You can find him inside Grommash Hold in Orgrimmar's Valley of Strength. It must be an important matter for him to send for you so directly, {name}.", sourceObjective = "Speak with Tyelis at Grommash Hold in Orgrimmar's Valley of Strength.", completion = "The Horde has need of your talents, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28308] = { id = 28308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Seer Liwatha", description = "Seer Liwatha sends her greetings from the Valley of Wisdom in Orgrimmar, {name}. She asked me to convey an invitation to visit her next time you're in the city. It sounded like she has something of importance to discuss with you.", sourceObjective = "Speak with Seer Liwatha in Orgrimmar's Valley of Wisdom.", sourceObjectiveStatus = "unverified-source-field" }
quests[28309] = { id = 28309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Shadow-Walker Zuru", description = "Shadow-Walker Zuru, a revered priest trainer, has asked to meet with you in Orgrimmar. You can find him in the Valley of Spirits with the other Darkspear trainers. It must be an important matter for him to send for you so directly, {name}.", sourceObjective = "Speak with Shadow-Walker Zuru in Orgrimmar's Valley of Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[28310] = { id = 28310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan's Vigil", description = "Our work here in Chiselgrip is done, mostly thanks to you.  We'll now be moving on to the east, to Morgan's Vigil.\n\nOur intel indicates that Morgan's Vigil has been vacated, as most of its inhabitants have moved into Blackrock Mountain to fight their own battle against the Blackrocks.  It should serve as a sufficient base of operations for the final stages of our plan.\n\nOf course, Keeshan will be joining you on the road.  As will I.", sourceObjective = "Report to Oralius at Morgan's Vigil in Burning Steppes.", completion = "You've arrived!  And just in time for the friendship ceremony!\n\n<Oralius looks wistfully over his shoulder at the ogre head, and quickly becomes panicked.>\n\nCaptain Winky!  Where'd Captain Winky go?\n\nNo, don't tell me he got cold feet!", sourceObjectiveStatus = "unverified-source-field" }
quests[28311] = { id = 28311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackened Ashes", description = "I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we're going to do this, we're going to do it right, and that means being prepared.\n\nI need ash, {name}.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the northwest.  The stuff is deep, deep black, which is what we need for our next disguise.\n\nDon't worry, you've already got a disguise.  This one is for someone... well, someTHING... else.", sourceObjective = "Obtain 9 piles of Obsidian Ash.", progress = "The ashes of the obsidian elementals are particularly dark - exactly what we need for our purposes.", completion = "Yes, these will do.  I will get this packed up for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28312] = { id = 28312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Demons of the Land", description = "The lava beds nearby - to the west - play host to flamekin, a brand of fire demon that has long roamed the steppes.  Situations are such in the Blackrock army that, if we are careful, we may be able to sneak some of these flamekin behind enemy lines to cause some havoc.\n\nBring me the bodies of several flamekin.  As demons, they are easily resurrected, and then we can use them for our own purposes.", sourceObjective = "Obtain 18 Fallen Flamekin.", progress = "The flamekin are weak, but they travel in packs.  Be cautious.", completion = "To the untrained eye, these will look exactly like imps.\n\nWe just need to get them to that untrained eye.  I'll work on preparing them for delivery.", sourceObjectiveStatus = "unverified-source-field" }
quests[28313] = { id = 28313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heap of Delicious Worg", description = "We're going to need fresh meat, which means you're going to be hunting worg.  The worg on this side of the steppes should be your target.\n\n<Troteman produces a large blade, which he hands to you.>\n\nHunt the giant ember worgs.  Once you've killed them, use this saw to remove the choicest bits of meat from their bodies.  You will find these worgs all over the steppes, but the closest pack rules the land just to our northeast.", sourceObjective = "Use the Worgsaw on the bodies of slain Giant Ember Worgs to obtain 40 Worg Cutlets.", progress = "Any luck out there?", completion = "This meat looks good... but I think it needs a little \"seasoning\".  I'll make sure that gets taken care of.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28314] = { id = 28314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Tour", description = "My legs are getting a little restless again.  You interested in taking a little tour, {name}?\n\nWe're going to take a trip around Dreadmaul Rock.  I'd like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we're on the way.", sourceObjective = "Kill 25 Black Dragonspawn or Black Wyrmkin.", completion = "<Keeshan is covered in blood and sweat.>\n\nThat was exactly what I needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28315] = { id = 28315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Vanguard", description = "The Blackrock orcs don't come alone.  You've already seen that they've got the Firegut ogres and Smolderthorn trolls on their side.  Unfortunately for us, they're also teamed up with the black dragonflight.\n\nThe orcs and the dragons have already sent some of their champions to stand guard at rally points, which are marked by a dragon skull on a pike.  You and I are going to find these rally points and take out this vanguard before the battle starts.\n\nReady?", sourceObjective = "Slay Minyoth, Whelptamer Akumi, Terromath the Seared, and Tugnar Goremaw.", progress = "Come on, {name}, there's still more of them left.  Our job isn't done.", completion = "Your kill count is adding up, {name}.  We're chipping away at them.\n\nAnd we are going to win.  Redridge will NOT fall to these cowards.", sourceObjectiveStatus = "unverified-source-field" }
quests[28316] = { id = 28316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deal With a Dragon", description = "While we are circling around Dreadmaul Rock, there's one more stop that we need to make.\n\nYou remember the hatchlings that you freed from the Whelping Downs?  Troteman's been hanging onto them, and we're going to deliver them to someone who will take care of them better than we can.  He's staying in Slither Rock, to the northeast of Dreadmaul Rock.\n\nHis name is Acride, and he might be the key to victory in the upcoming battle.", sourceObjective = "Deliver the Rescued Whelplings to Acride at Slither Rock in Burning Steppes.", progress = "You've arrived, {name}.", completion = "Yes, the whelplings.  I will take care of them.\n\nAs for the agreement I made with your Colonel Troteman earlier, tell him that I will hold up my end of the bargain.  You will have your dragon for the battle against the orcs.\n\nWe hold no particular love for the Redridge Mountains, but we do share your grudge against the Blackrock clan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28317] = { id = 28317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Thorg'izog", description = "General Thorg'izog is staying among the ogres in the Firegut Furnace, a cave on the western edge of Dreadmaul Rock.  I'd like you to deliver this to him and the ogres.\n\nInside this package, you will find the worg cutlets you obtained, marinated in the fel slider cider that we took from the Altar of Storms.\n\nI would avoid eating it if I were you.\n\nBring it to General Thorg'izog.  He will make sure that his troops are fed and, with any luck, he will eat some himself.", sourceObjective = "Using your Blackrock Disguise, bring the Slider Cider-Marinated Cutlets to General Thorg'izog at Firegut Furnace in Burning Steppes. Speak with Colonel Troteman if you need a new Blackrock Disguise.", progress = "What've you got there, soldier?", completion = "Well would you look at that!  My favorite soldier comes through in the clutch!\n\nI'll make sure to get this distributed among the ogres.\n\nI'll see you in Redridge, soldier.  For the glory of the Blackrock!", sourceObjectiveStatus = "unverified-source-field" }
quests[28318] = { id = 28318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Neeralak", description = "The warlocks of the Blackrock Clan often practice their magic in the Skull Warren, a cave on the eastern side of Dreadmaul Rock.  Their leader, Xi'lun, is busy elsewhere, so the cave is currently being held by another of the big three: Dragon-Lord Neeralak.  And Neeralak's expertise is in dragons, not in necromancy.\n\nI've used the slumber sand on those flamekin you captured.  Try to convince Neeralak that they're warlock imps, and not flamekin.  When they wake up, they won't be happy.", sourceObjective = "Using your Blackrock Disguise, sneak into the Skull Warren and convince Dragon-Lord Neeralak to take your Crate of Sleeping Flamekin. Speak with Colonel Troteman if you need a new Blackrock Disguise.", progress = "What?", completion = "What are these?  Oh, are these imps?\n\nI'm pretty sure that imps don't just fall asleep in boxes!\n\nI'll take your word for it, though.  I don't understand any of this warlock crap.  Leave them in the corner.", sourceObjectiveStatus = "unverified-source-field" }
quests[28319] = { id = 28319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Xi'lun", description = "Intel tells us that High Warlock Xi'lun - the final member of the Big Three - is within the cave atop Dreadmaul Peak, preparing for his big moment.\n\nHe is waiting for a delivery: an Orb of Domination, with which he can perform a powerful summoning ritual.  I want you to give him this:\n\n<Troteman hands you a glass orb.>\n\nThis is the clear glass orb that you freed from the Altar of Storms.  It is powerless.  Give it to Xi'lun, and cross your fingers that he doesn't notice.", sourceObjective = "While using the Blackrock Disguise, deliver the Clear Glass Orb to High Warlock Xi'lun atop Dreadmaul Rock in Burning Steppes.", progress = "I don't have time for games, fool.  Get out of my sight.", completion = "Pff!  You're late!  Do you know how long I've been waiting for Ner'gosh to deliver this orb?\n\n<Xi'lun looks down at the orb, then up at you.>\n\nThere's something strange about this orb... it's too...\n\n<Xi'lun trails off.>\n\nNever mind, it must be my nerves talking.  Thank you for the delivery.  For blood and honor!", sourceObjectiveStatus = "unverified-source-field" }
quests[28320] = { id = 28320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Dreadmaul Rock", description = "This is it, {name}.  This is where it hits the fan.  Where all the pieces come together.\n\nStrap in, and come with me.  We're going to go talk to Acride and call in that favor that he owes us.  Then we'll stop this invasion of Redridge before it even starts.", sourceObjective = "Slay 200 Blackrock Invaders. If you should lose your vehicle, use the Horn of the Callers to summon it again.", completion = "Did you see them run?  They didn't know what was happening!  Beautiful!\n\nOur job's almost done, {name}.  It's time to deliver the deathblow.", sourceObjectiveStatus = "unverified-source-field" }
quests[28321] = { id = 28321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glory Amidst Chaos", description = "You and Keeshan are going back to that mountain.  There's three orcs who survived the attack, and we won't rest until they're dead.\n\nThat's right, I'm talking about the Big Three.\n\nGeneral Thorg'izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain's peak.  Xi'lun is in the back of the Skull Warren, plotting with his fellow warlocks.\n\nLeave your mark, {name}.  Hunt down those sniveling Blackrocks, and teach them the might of Redridge!", sourceObjective = "Kill General Thorg'izog, Dragon-Lord Neeralak, and High Warlock Xi'lun.", completion = "<Colonel Troteman is beaming.>\n\nWelcome home, boys.", sourceObjectiveStatus = "unverified-source-field" }
quests[28322] = { id = 28322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spoils of War", description = "We've toppled a giant today, {name}.  While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near Redridge anytime soon.  You and Keeshan saw to that.\n\nI'd say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.\n\nThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.", sourceObjective = "Inspect the Box of Left Over Supplies at Morgan's Vigil in Burning Steppes.", completion = "You peer inside, and find...", sourceObjectiveStatus = "unverified-source-field" }
quests[28323] = { id = 28323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Brother Silverhallow", description = "Brother Silverhallow sent word that he wishes to speak with you. Next time you're in Orgrimmar, visit him in the Goblin Slums.  It sounded like he had something important on his mind.", sourceObjective = "Speak with Brother Silverhallow in Orgrimmar's Goblin Slums.Brother Silverhallow sent word that he wishes to speak with you. Next time you're in Orgrimmar, visit him in the Goblin Slums. It sounded like he had something important on his mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28324] = { id = 28324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Studies in Lethality", description = "We used a fairly potent strain of blight against the humans of Southshore. As you can see, it worked. The trouble with blight use, though, is that blight tends to stick around after it's served its purpose.\n\nWhat I need from you is to take this testing kit and get out into the field to get a lethality count from the blight slimes that we've released into the area. Use the lethality analyzer on the blight slimes sweeping the slime pools. Come back to me when you have some solid data.", sourceObjective = "Recover 250 Blight Samples.", completion = "Oh my. 250? This thing doesn't go past 250. How are you still standing? You should be a puddle of goo by now. Sylvanas will be most displeased with this information. There might be some things we can do to reduce the lethality levels of the area by a few decades, but that still leaves us out by about a hundred or so years.", sourceObjectiveStatus = "unverified-source-field" }
quests[28325] = { id = 28325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Living", description = "Recycling! It's all the craze these days. The Banshee Queen has decreed that we must conserve if we are to prosper as a people. Everyone must do their part, right? With that said, you will be doing our part for us.\n\nThere are likely thousands of blight canister bits and pieces all over Southshore. We can reuse those canisters for more blight bombing goodness. Just head into the ruins here and pick up whatever you can find.", sourceObjective = "Recover 8 Used Blight Canisters.", progress = "Bring me those canisters!", completion = "Excellent work, {name}. You are incredibly resilient to this blight. We'll have to take you in for testing some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28326] = { id = 28326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing the Pawns", description = "{name}.  It sounds like you and Keeshan have finished with your tasks.  I've also finished mine.\n\nReturn to Morgan's Vigil.  I've prepared a few packages to deliver to the Big Three: Thorg'izog, Neeralak, and Xi'lun.  You've already met General Thorg'izog.  This will be your chance to meet the other two.\n\nThat is, before we kill them.", sourceObjective = "Return to Colonel Troteman at Morgan's Vigil in Burning Steppes.", completion = "Good, you're back.\n\nI hope you've still got that disguise.  You're going back undercover, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28327] = { id = 28327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locked and Loaded", description = "{name}, come in.  Can you read me?\n\nThe battle is about to start.  I hope you've delivered all of those packages.\n\nI need you here in Morgan's Vigil, NOW.", sourceObjective = "Report to Colonel Troteman at Morgan's Vigil in Burning Steppes.", completion = "{name}'s here!  We can get started.\n\nThis is our big moment, {name}.  I hope you brought your A game.", sourceObjectiveStatus = "unverified-source-field" }
quests[28328] = { id = 28328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer reaches far and wide. They search ceaselessly for allies in their battle against us and they are recruiting the Dark Iron dwarves of Blackrock Depths to their cause.\n\nMoira's grip on the Dark Irons is tenuous at best and more of her people fall away from her rule with each day. We must sabotage their recruitment efforts.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", sourceObjective = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", completion = "You have done your work well, {name}. While this will not stop Twilight's Hammer, it will help sow suspicion between them and the Dark Irons.", sourceObjectiveStatus = "unverified-source-field" }
quests[28329] = { id = 28329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angry Scrubbing Bubbles", description = "These blight slimes seem to be really angry. They've even got a faint outline of an angry humanoid face in their ectoplasm. You don't think Hinott would be too happy about having non-compliant slimes working the slime pools.\n\nKill any angry blight slimes that you see and try to get a lock on a breeding pool.", sourceObjective = "Kill 5 Angry Blight Slimes.", completion = "All signs indicate to a breeding pool being inside the ruined town hall. You'll need to investigate!", sourceObjectiveStatus = "unverified-source-field" }
quests[28330] = { id = 28330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of Filth", description = "The trail of filth and anger leads into the ruined town hall. Surely there is a slime breeding pool inside the structure. Fight your way inside and deal with whatever angry slime-breeder that you encounter!\n\nShould you succeed Serge Hinott at the Ruins of Southshore will surely want to hear about it.", sourceObjective = "Kill Chet the Slime-Breeder.", completion = "Perhaps with Chet vanquished, the lethality levels of this place will decrease a tad faster. A job well done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28331] = { id = 28331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helcular's Rod Giveth...", description = "To think, I, a master of necromancy, trained by Kel'Thuzad himself, was reduced to nothing more than a corpse in a grave. Thankfully, my astute apprentice, Thaivand, managed to find a group of heroes to recover this:\n\n<Helcular whips out his rod.>\n\nIt is through the power of the rod that I was reborn. The rod giveth and the rod taketh away!\n\nTake it now and use it to empower our dark rangers battling the worgen in the field north of us. Renew their vigor with my rod.", sourceObjective = "Use Helcular's Rod to Empower 8 Dark Rangers.", completion = "As I said, the rod giveth to our dark rangers and doth taketh away from our enemy!", sourceObjectiveStatus = "unverified-source-field" }
quests[28332] = { id = 28332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helcular's Command", description = "Our dark rangers search the fields for worgen terrorists. These worgen have been sent out by their dark masters to hunt and kill us. And though a dark ranger is a formidable combatant, the worgen often attack in packs, which can overwhelm even a dark ranger.\n\nSearch the fields around the ruins of Southshore for Bloodfang forsaken hunters. Kill any that you see! For the Forsaken and for Lordaeron!", sourceObjective = "Kill 15 Bloodfang Forsaken Hunters.", completion = "We should have killed Bloodfang in Silverpine. It's a shame he still lives. It's an even bigger shame that we have as of yet been unable to turn worgen into undead. Surely there is a way...", sourceObjectiveStatus = "unverified-source-field" }
quests[28333] = { id = 28333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Time to Oil Up", description = "Three things come out of Irontree Clearing: lumber, oil, and exhausted workers. The first two are pretty much the cause of the third, but I like to be efficient about things where I can.\n\nI've got our shredders working triple unpaid overtime, and there's really nowhere in the schedule for them to get maintenance.\n\nUse this grappling hook to nab some of the extra oil cans floating around camp and use them to oil up the shredders, would you?", sourceObjective = "Use Darla's Grapple to collect Irontree Oil Cans and use them to oil 7 Irontree Shredders.", completion = "Efficiency in the workforce! Wonderful.\n\nMaybe I should check on the goblins inside those shredders later.", sourceObjectiveStatus = "unverified-source-field" }
quests[28334] = { id = 28334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flare Fight", description = "This operation's stayed pretty discreet so far, but the worgen over in Talonbranch Glade have it out for us. They've been trying everything they can to get us shut down.\n\nSome of the workers have told me they've seen glimpses of worgen lurking around the clearing. Take these oversized megaflares. They're bright enough to show anything that gets anywhere near them.\n\nUse the flares to look for prowling worgen, and make sure they don't leave here alive!", sourceObjective = "Use Darla's Box of Megaflares to reveal 8 Talonbranch Prowlers and slay them.", completion = "Mangy curs think they can just waltz in here and ruin my finely-tuned operation. Hah!\n\nI told you not to look directly at the flares, right? Oops.", sourceObjectiveStatus = "unverified-source-field" }
quests[28335] = { id = 28335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn It Off! Turn It Off!", description = "It was those darn worgen! They blew right past me into the cavern.\n\nThey must've messed with the Master Control Pump! If that thing is left on too long, every pipe runnin' under our feet is gonna blow. You think the leaks now are bad? Just wait!\n\nListen, if you can reach the Master Control Pump all the way in the back of the cavern, you can shut it off and save us all!", sourceObjective = "Shut off the Master Control Pump at the bottom of Irontree Cavern.", completion = "You turn the largest handle you can find on the Master Control Pump, and the rattling noises in the nearby pipes stop.\n\nThis gives you a few moments to hear the sound of flames outside before a familiar voice cuts in through a tinny, crackling speaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[28336] = { id = 28336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slap and Cap", description = "Oh for... not again! If you heard the deputy yelling out there, that means we've got a fullblown oil leak on our hands! It's those filthy worgen again!\n\nListen, it's going to be total chaos out there. Sleep-deprived goblins running around screaming and not knowing what to do. I need you to snap the workers back to their senses.\n\nA good, swift backhand across the face should do it! Once they shake themselves off, they'll get to work capping those gushers!", sourceObjective = "Slap 7 Panicked Workers to make them cap the oil gushers.", completion = "It's not working! We're going to have to shut it off at the source.\n\nGo talk to the Deputy outside, he'll walk you through it!", sourceObjectiveStatus = "unverified-source-field" }
quests[28337] = { id = 28337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shredders of Irontree", description = "Disgusting, isn't it? Look at them. Pathetic little things that can't even toil with their own bodies.\n\nThey stomp around in their massive metal shredders, carving the forest to splinters. I bet they think they're safe in there, all warm and cozy.\n\nProve them wrong. Blaze north through the camp and destroy as many shredders as you can. Once you've spilled some blood, we're going to take this place apart for good.", sourceObjective = "Kill 9 Irontree Shredders.", completion = "This is but the first strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[28338] = { id = 28338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, {name} - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.", sourceObjective = "Kill 15 Deadwood Furbolg of any kind in Felpaw Village.", completion = "I sense that you have achieved victory.  Victory... such a hollow word considering what had to be done.  Regardless, you've proven yourself to be worthy of our trust.\n\nIt may take some time before the Timbermaw welcome you without hostility within the Hold.  Still, your perseverance will erode any suspicion my brethren may have about you.  So long as you never betray us and raise weapons against us, we will find common ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[28339] = { id = 28339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is Your Oil Running?", description = "Last time we had an oil leak this bad, the oil itself tried to get away!\n\nI don't know what does it, maybe all the demon goop floating around here, but when we get a big enough crude leak half of it globs together and tries to run away.\n\nThat's profit trying to escape! Go run after those oil sludges and bring back their sweet, precious oil!", sourceObjective = "Collect 10 Crude Tarballs from Oily Sludges.", progress = "That stuff better not still be moving when you bring it back here.", completion = "Thank goodness the oil is safe! Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28340] = { id = 28340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bomb Deal", description = "All my workers got driven straight out of the cavern here by those big swamp-lookin' things! Darla's sent me here to pick up the pieces, but have you seen it in there? I ain't goin' in!\n\nThere's a ton of explosives left behind that we can't just leave layin' around\n\n I'll make you a deal: You run in there and get those explosives gathered up, and I will stay here and not get killed by swamp-things, and if you don't either, I'll pay ya! How's that sound?", sourceObjective = "Collect 8 Irontree Explosives from Irontree Cavern.", progress = "We had a deal, right? Right?", completion = "Hey, nice! I'll just take those... carefully...\n\nDon't go tellin' the workers I didn't have the guts to go down there myself, you hear? Here's your pay... and a little somethin' extra.", sourceObjectiveStatus = "unverified-source-field" }
quests[28341] = { id = 28341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Corruption", description = "Though we druids shun the demonic powers infesting this land, it must still be confronted.\n\nShatter Scar Vale to the south seethes with corruption. The energies there are so chaotic that they manifest as violent entities, pure fel magic given form to lash out at all life.\n\nI have been keeping a close eye on these chaotic beasts, and studying their strength. I need to make sure they are still weakening with time. Bring me the essences they drop, so I may ensure they are diminishing.", sourceObjective = "Collect 8 Entropic Essences from Entropic Horrors in Shatter Scar Vale.", progress = "Be wary with the essence. It is as poisonous as it is powerful.", completion = "I can tell just from the size of these that the fel taint is healing. Slowly... but significantly.\n\nThank you, {name}. I will ensure these are properly purged.", sourceObjectiveStatus = "unverified-source-field" }
quests[28342] = { id = 28342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel To Pieces", description = "The infernals that lurk in Shatter Scar Vale are formidable, but not invincible. Much progress has been made in thinning their numbers\n\nDestroying them is only part of the solution, however. I've found that the stone that infernals are made of still contains large amounts of fel magic even after the infernal's death.\n\nThe rubble of slain infernals now litters Shatter Scar Vale, leeching its corruption back into the ground. If you could collect it and bring it to me, I would be grateful.", sourceObjective = "Collect 9 pieces of Infernal Debris from Shatter Scar Vale.", progress = "Do be sure to pick up after your own kills, as well.", completion = "It's good to see someone who cares about keeping the forest clean. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28343] = { id = 28343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Breath of Cenarius", description = "{name}, we have learned that a missing Cenarion artifact has surfaced in the hands of a Twilight's Hammer pyromancer. Pyromancer Loregrain has taken this artifact, the Breath of Cenarius, into Blackrock Depths and uses its power to open elemental gates.\n\nWe must act to keep Loregrain from summoning elementals to bolster the ranks of his Dark Iron allies. Recover the artifact from him and use its power to close the gates that Loregrain has been using.", sourceObjective = "Recover the Breath of Cenarius from Pyromancer Loregrain in Blackrock Depths and use the artifact to close 3 Elemental Gates.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "I'm heartened to have the Breath of Cenarius back where it belongs and I know the rest of the circle will be impressed by your efforts. You may have also set back the plans of the Twilight's Hammer clan a bit, too. Excellent work.", sourceObjectiveStatus = "unverified-source-field" }
